def _finish_bounded_blocking_worker(
    worker: asyncio.Task[Any],
    *,
    slots: asyncio.BoundedSemaphore,
) -> None:
    slots.release()
    if not worker.cancelled():
        worker.exception()


async def _run_bounded_blocking(
    slots: asyncio.BoundedSemaphore,
    function: Callable[..., Any],
    /,
    *args: Any,
    **kwargs: Any,
) -> Any:
    await slots.acquire()
    try:
        worker = asyncio.create_task(
            asyncio.to_thread(function, *args, **kwargs)
        )
    except BaseException:
        slots.release()
        raise
    worker.add_done_callback(
        lambda completed, worker_slots=slots: _finish_bounded_blocking_worker(
            completed,
            slots=worker_slots,
        )
    )
    return await asyncio.shield(worker)


@app.middleware("http")
async def csrf_middleware(request: Request, call_next):
    from serverware import control_plane_oidc_session_activation_recovery_routes as recovery_routes
    from serverware import portal_session_activation_confirmation_routes as confirmation_routes
    from serverware import control_plane_workload_identity_routes as workload_routes

    if request.scope.get("path") in workload_routes.PATHS:
        try:
            _require_registration_execution_session_csrf(request)
        except HTTPException as exc:
            return workload_routes.error(exc.status_code)
        return await call_next(request)

    if request.scope.get("path") == confirmation_routes.POST_PATH:
        try:
            _require_registration_execution_session_csrf(request)
        except HTTPException as exc:
            return confirmation_routes.error(exc.status_code)
        return await call_next(request)

    if request.scope.get("path") in recovery_routes.PATHS:
        # The old cookie is possession evidence only on this route. Do not
        # send it through generic current-session authentication even to
        # choose a CSRF branch; the actor repeats this exact cookie check.
        try:
            _require_registration_execution_session_csrf(request)
        except HTTPException as exc:
            return recovery_routes.error(exc.status_code, path=request.scope.get("path"))
        return await call_next(request)
    try:
        validate_csrf_request(request)
    except HTTPException as exc:
        from serverware import control_plane_oidc_session_activation_routes as activation_routes

        if request.scope.get("path") == activation_routes.POST_PATH:
            return activation_routes.error(exc.status_code)
        return JSONResponse(
            status_code=exc.status_code,
            content={"detail": exc.detail},
            headers=exc.headers,
        )
    response = await call_next(request)
    if request.method not in {"GET", "HEAD", "OPTIONS"}:
        try:
            await _run_bounded_blocking(
                _METADATA_AUDIT_OUTBOX_DRAIN_SLOTS,
                db.drain_metadata_audit_outbox,
                limit=100,
            )
        except Exception:
            pass
    return response


@app.middleware("http")
async def bounded_control_plane_request_middleware(request: Request, call_next):
    from serverware import control_plane_oidc_session_activation_routes as activation_routes
    from serverware import control_plane_oidc_session_activation_recovery_routes as recovery_routes
    from serverware import portal_session_activation_confirmation_routes as confirmation_routes
    from serverware import control_plane_workload_identity_routes as workload_routes

    if request.scope.get("path") in workload_routes.PATHS:
        refusal = await workload_routes._frame_request(request)
        if refusal is not None:
            return refusal
        return await call_next(request)

    if request.scope.get("path") == confirmation_routes.POST_PATH:
        refusal = await confirmation_routes._frame_request(request)
        if refusal is not None:
            return refusal
        return await call_next(request)

    if request.scope.get("path") in recovery_routes.PATHS:
        refusal = await recovery_routes._frame_request(request)
        if refusal is not None:
            return refusal
        return await call_next(request)

    if request.scope.get("path") == activation_routes.POST_PATH:
        refusal = await activation_routes._frame_request(request)
        if refusal is not None:
            return refusal
        # The dedicated core consumes only these bounded original bytes. Do
        # not apply the older registration parsers or read the stream twice.
        return await call_next(request)

    from serverware import control_plane_registration_handoff_routes as handoff_routes
    from serverware import control_plane_registration_handoff_http as handoff_contract
    from serverware import control_plane_registration_recovery_routes as recovery_routes
    from serverware import control_plane_registration_recovery_http as recovery_contract
    from serverware import control_plane_registration_finalization_routes as finalization_routes
    from serverware import control_plane_registration_finalization_http as finalization_contract
    from serverware import control_plane_registration_finalization_grant_routes as finalization_grant_routes
    from serverware import control_plane_registration_finalization_grant_http as finalization_grant_contract
    from serverware import control_plane_registration_finalization_reservation_routes as finalization_reservation_routes
    from serverware import control_plane_registration_finalization_reservation_http as finalization_reservation_contract
    from serverware import control_plane_registration_finalization_sql_routes as finalization_sql_routes
    from serverware import control_plane_registration_finalization_sql_http as finalization_sql_contract
    from serverware import control_plane_registration_finalization_completion_routes as finalization_completion_routes
    from serverware import control_plane_registration_finalization_completion_http as finalization_completion_contract
    from serverware import control_plane_oidc_session_activation_permission_routes as activation_permission_routes
    from serverware import control_plane_oidc_session_activation_permission_http as activation_permission_contract
    from serverware import control_plane_oauth_measured_refresh as measured_refresh_contract
    from serverware import control_plane_oauth_measured_cleanup as measured_cleanup_contract
    from serverware import control_plane_oauth_measured_pending_retirement as pending_retirement_contract
    from serverware import control_plane_oauth_measured_capture_retirement as capture_retirement_contract

    request_path = request.scope.get("path")
    from serverware import control_plane_oauth_measured_exchange as native_issuance_contract
    handoff_request = (request.method == "POST" and request_path in (
        handoff_routes.EXECUTE_PATHS | handoff_routes.COMPLETE_PATHS))
    handoff_completion = request_path in handoff_routes.COMPLETE_PATHS
    recovery_request = request.method == "POST" and request_path in recovery_routes.PATHS
    finalization_request = request.method == "POST" and request_path in finalization_routes.PATHS
    finalization_grant_request = request.method == "POST" and request_path in finalization_grant_routes.PATHS
    finalization_reservation_request = request.method == "POST" and request_path in finalization_reservation_routes.PATHS
    finalization_sql_request = request.method == "POST" and request_path in finalization_sql_routes.PATHS
    finalization_completion_request = (
        request.method == "POST" and request_path in finalization_completion_routes.PATHS)
    finalization_completion_recovery = request_path in finalization_completion_routes.RECOVERY_PATHS
    finalization_completion_options = request_path in finalization_completion_routes.OPTIONS_PATHS
    activation_permission_request = (
        request.method == "POST" and request_path in activation_permission_routes.PATHS)
    reservation_request = (
        request.method == "POST" and request_path in _REGISTRATION_RESERVATION_PATHS
    )
    execution_preparation_request = (
        request.method == "POST" and request_path in _REGISTRATION_EXECUTION_PREPARATION_PATHS
    )
    registration_preparation_request = (
        request.method == "POST" and request_path in _REGISTRATION_PREPARATION_PATHS
    ) or execution_preparation_request or reservation_request or handoff_request or recovery_request or finalization_request or finalization_grant_request or finalization_reservation_request or finalization_sql_request or finalization_completion_request or activation_permission_request
    preparation_error = (_registration_reservation_error if reservation_request
        else _registration_execution_preparation_error if execution_preparation_request
        else _registration_preparation_error)
    if handoff_request:
        preparation_error = lambda status, code: handoff_routes.error(
            status, code, completion=handoff_completion)
    elif recovery_request:
        preparation_error = recovery_routes.error
    elif finalization_request:
        preparation_error = finalization_routes.error
    elif finalization_grant_request:
        preparation_error = finalization_grant_routes.error
    elif finalization_reservation_request:
        preparation_error = finalization_reservation_routes.error
    elif finalization_sql_request:
        preparation_error = finalization_sql_routes.error
    elif finalization_completion_request:
        preparation_error = lambda status, code: finalization_completion_routes.error(
            status, code, recovery=finalization_completion_recovery)
    elif activation_permission_request:
        preparation_error = activation_permission_routes.error
    if registration_preparation_request:
        # This new route family has one exact framing path. Do not change the
        # existing browser /verify parser, defaults or finalization behavior.
        lengths = request.headers.getlist("content-length")
        if not lengths:
            return preparation_error(411, "registration_preparation_length_required")
        if (len(lengths) != 1 or re.fullmatch(r"[1-9][0-9]{0,5}", lengths[0]) is None
                or request.headers.getlist("transfer-encoding")
                or request.headers.getlist("content-encoding")
                or request.scope.get("query_string", b"") != b""):
            return preparation_error(400, "registration_preparation_framing_invalid")
        if request.headers.getlist("content-type") != ["application/json"]:
            return preparation_error(415, "registration_preparation_json_required")
        route_limit = (activation_permission_contract.MAX_REQUEST_BYTES if activation_permission_request
            else finalization_completion_contract.MAX_REQUEST_BYTES if finalization_completion_request
            else finalization_sql_contract.MAX_REQUEST_BYTES if finalization_sql_request
            else finalization_reservation_contract.MAX_REQUEST_BYTES if finalization_reservation_request
            else finalization_grant_contract.MAX_REQUEST_BYTES if finalization_grant_request
            else finalization_contract.MAX_REQUEST_BYTES if finalization_request
            else recovery_contract.MAX_REQUEST_BYTES if recovery_request
            else handoff_contract.MAX_REQUEST_BYTES if handoff_request else _REGISTRATION_PREPARATION_MAX_BYTES)
        if int(lengths[0]) > route_limit:
            return preparation_error(413, "registration_preparation_body_too_large")
    setup_canary_request = (
        request.method == "POST"
        and isinstance(request_path, str)
        and re.fullmatch(
            r"/api/setup/sessions/[^/]{1,512}/canary", request_path
        )
        is not None
    )
    strict_json_request = (
        request.method == "POST"
        and (
            request_path
            in {
                "/api/authority/control-plane/execute",
            "/api/authority/control-plane/custody/reconcile",
            "/api/authority/webauthn/challenges",
            "/api/data-plane/policy-candidate/artifact",
            "/api/policy/authority/candidates/package",
            "/api/policy/authority/candidates/handoff",
            "/api/data-plane/policy-canary/evidence",
            }
            or setup_canary_request
            or registration_preparation_request
        )
    )
    public_evidence_request = (
        request.method == "POST"
        and request_path == "/attestation/public-evidence"
    )
    if strict_json_request:
        if request.scope.get("query_string", b""):
            return JSONResponse(
                status_code=400,
                content={"detail": "authority route does not accept a query string"},
            )
        if request.headers.get("content-type") != "application/json":
            return JSONResponse(
                status_code=415,
                content={"detail": "authority route requires application/json"},
            )
        if request.headers.get("content-length") is None:
            return JSONResponse(
                status_code=411,
                content={"detail": "authority route requires Content-Length"},
            )
    request_limit = {
        **{path: activation_permission_contract.MAX_REQUEST_BYTES for path in activation_permission_routes.PATHS},
        **{path: handoff_contract.MAX_REQUEST_BYTES for path in (
            handoff_routes.EXECUTE_PATHS | handoff_routes.COMPLETE_PATHS)},
        **{path: recovery_contract.MAX_REQUEST_BYTES for path in recovery_routes.PATHS},
        **{path: finalization_contract.MAX_REQUEST_BYTES for path in finalization_routes.PATHS},
        **{path: finalization_grant_contract.MAX_REQUEST_BYTES for path in finalization_grant_routes.PATHS},
        **{path: finalization_reservation_contract.MAX_REQUEST_BYTES for path in finalization_reservation_routes.PATHS},
        **{path: finalization_sql_contract.MAX_REQUEST_BYTES for path in finalization_sql_routes.PATHS},
        **{path: finalization_completion_contract.MAX_REQUEST_BYTES for path in finalization_completion_routes.PATHS},
        "/api/authority/control-plane/execute":
            _POLICY_AUTHORITY_TRANSACTION_REQUEST_MAX_BYTES,
        "/api/authority/control-plane/custody/reconcile": 256,
        "/api/policy/file-publication/genesis-materialize": 24 * 1024 * 1024,
        "/api/data-plane/oauth-refresh": measured_refresh_contract.MAX_REQUEST,
        "/api/data-plane/oauth-refresh-cleanup": measured_cleanup_contract.MAX_REQUEST,
        "/api/data-plane/oauth-pending-retirement": pending_retirement_contract.MAX_REQUEST,
        "/api/data-plane/oauth-capture-retirement": capture_retirement_contract.MAX_REQUEST,
        "/api/webauthn/register/prepare": _REGISTRATION_PREPARATION_MAX_BYTES,
        "/api/auth/session/webauthn/register/prepare": _REGISTRATION_PREPARATION_MAX_BYTES,
        "/api/webauthn/register/prepare-execution": _REGISTRATION_PREPARATION_MAX_BYTES,
        "/api/auth/session/webauthn/register/prepare-execution": _REGISTRATION_PREPARATION_MAX_BYTES,
        "/api/webauthn/register/reserve-execution": _REGISTRATION_PREPARATION_MAX_BYTES,
        "/api/auth/session/webauthn/register/reserve-execution": _REGISTRATION_PREPARATION_MAX_BYTES,
        "/api/authority/webauthn/challenges":
            _POLICY_AUTHORITY_TRANSACTION_REQUEST_MAX_BYTES,
        "/api/data-plane/policy-candidate/artifact":
            _POLICY_AUTHORITY_HANDOFF_REQUEST_MAX_BYTES,
        "/api/policy/authority/candidates/package":
            _POLICY_AUTHORITY_HANDOFF_REQUEST_MAX_BYTES,
        "/api/policy/authority/candidates/handoff":
            _POLICY_AUTHORITY_HANDOFF_REQUEST_MAX_BYTES,
        "/api/data-plane/policy-canary/evidence":
            _POLICY_CANARY_EVIDENCE_REQUEST_MAX_BYTES,
        **{path: native_issuance_contract.MAX_REQUEST for path in native_issuance_contract.HUMAN_PATHS},
        native_issuance_contract.MACHINE_PATH: native_issuance_contract.MAX_REQUEST,
        native_issuance_contract.RECOVERY_PATH: 1024,
    }.get(
        request_path,
        (
            _POLICY_AUTHORITY_HANDOFF_REQUEST_MAX_BYTES
            if setup_canary_request
            else
            _PUBLIC_EVIDENCE_REQUEST_MAX_BYTES
            if public_evidence_request
            else _CONTROL_PLANE_REQUEST_MAX_BYTES
        ),
    )
    if public_evidence_request:
        raw_query = request.scope.get("query_string", b"")
        if type(raw_query) is not bytes or raw_query:
            return JSONResponse(
                status_code=400,
                content={
                    "detail":
                    "public attestation evidence does not accept a query string"
                },
            )
        if request.headers.get("content-type") != "application/json":
            return JSONResponse(
                status_code=415,
                content={
                    "detail":
                    "public attestation evidence requires application/json"
                },
            )
    raw_content_length = request.headers.get("content-length")
    if raw_content_length is not None:
        try:
            content_length = int(raw_content_length)
        except ValueError:
            return JSONResponse(
                status_code=400, content={"detail": "invalid Content-Length"}
            )
        if content_length < 0:
            return JSONResponse(
                status_code=400, content={"detail": "invalid Content-Length"}
            )
        if content_length > request_limit:
            return JSONResponse(
                status_code=413,
                content={
                    "detail": "request body exceeds its fixed route limit"
                },
            )
    if public_evidence_request:
        return await call_next(request)
    if request.method not in {"GET", "HEAD", "OPTIONS"}:
        body = bytearray()
        async for chunk in request.stream():
            if (registration_preparation_request
                    and len(chunk) > content_length - len(body)):
                return preparation_error(400, "registration_preparation_framing_invalid")
            body.extend(chunk)
            if len(body) > request_limit:
                return JSONResponse(
                    status_code=413,
                    content={"detail": "request body exceeds its fixed route limit"},
                )
        request._body = bytes(body)
        request._stream_consumed = False
        if registration_preparation_request:
            if len(body) != content_length:
                return preparation_error(400, "registration_preparation_framing_invalid")
            try:
                if activation_permission_request:
                    activation_permission_contract.parse_request(request._body, options=True)
                    request.state.oidc_session_activation_permission_bytes = request._body
                elif finalization_completion_request:
                    request.state.registration_finalization_completion_payload = (
                        finalization_completion_contract.parse_request(request._body,
                            recovery=finalization_completion_recovery,
                            options=finalization_completion_options))
                elif finalization_sql_request:
                    request.state.registration_finalization_sql_payload = finalization_sql_contract.parse_request(request._body)
                elif finalization_reservation_request:
                    request.state.registration_finalization_reservation_payload = finalization_reservation_contract.parse_request(request._body)
                elif finalization_grant_request:
                    request.state.registration_finalization_grant_payload = finalization_grant_contract.parse_request(request._body)
                elif finalization_request:
                    request.state.registration_finalization_payload = finalization_contract.parse_request(request._body)
                elif recovery_request:
                    request.state.registration_recovery_payload = recovery_contract.parse_request(request._body)
                elif handoff_request:
                    request.state.registration_handoff_payload = handoff_contract.parse_request(
                        request._body, completion=handoff_completion)
                else:
                    document = parse_strict_json_object(request._body,
                        limits=_REGISTRATION_PREPARATION_JSON_LIMITS)
                if reservation_request:
                    request.state.registration_reservation_payload = (
                        WebAuthnRegistrationReservation.model_validate(_plain_setup_json(document))
                    )
                elif execution_preparation_request:
                    request.state.registration_execution_preparation_payload = (
                        WebAuthnRegistrationExecutionPrepare.model_validate(_plain_setup_json(document))
                    )
                elif not handoff_request and not recovery_request and not finalization_request and not finalization_grant_request and not finalization_reservation_request and not finalization_sql_request and not finalization_completion_request and not activation_permission_request:
                    request.state.registration_preparation_payload = (
                        WebAuthnRegistrationPrepare.model_validate(_plain_setup_json(document))
                    )
            except (ReceiptVerificationError, ValidationError, ValueError, RecursionError):
                return preparation_error(400, "registration_preparation_json_invalid")
    response = await call_next(request)
    if (reservation_request or strict_json_request or request_path == "/api/policy/canary/status"
            or isinstance(request_path, str)
            and request_path.startswith("/api/authority/control-plane/custody")):
        response.headers["Cache-Control"] = "no-store"
        response.headers["Pragma"] = "no-cache"
    return response


class _BufferedHttpResponse:
    def __init__(self, *, max_body_bytes: int) -> None:
        self.max_body_bytes = max_body_bytes
        self.status_code: int | None = None
        self.headers: list[tuple[bytes, bytes]] = []
        self.body = bytearray()
        self.complete = False
        self.too_large = False

    async def send(self, message: Message) -> None:
        message_type = message.get("type")
        if message_type == "http.response.start":
            self._start(message)
            return
        if message_type == "http.response.body":
            self._body(message)
            return
        raise RuntimeError(
            "downstream HTTP response used an unsupported ASGI message"
        )

    def _start(self, message: Message) -> None:
        if self.status_code is not None or self.complete:
            raise RuntimeError("downstream HTTP response started more than once")
        status_code = message.get("status")
        if type(status_code) is not int or not 100 <= status_code <= 599:
            raise RuntimeError("downstream HTTP response status is invalid")
        if message.get("trailers", False):
            raise RuntimeError(
                "downstream HTTP response trailers cannot be signed"
            )
        raw_headers = message.get("headers", [])
        if not isinstance(raw_headers, list):
            raise RuntimeError("downstream HTTP response headers are invalid")
        copied_headers: list[tuple[bytes, bytes]] = []
        for header in raw_headers:
            if (
                not isinstance(header, tuple)
                or len(header) != 2
                or type(header[0]) is not bytes
                or type(header[1]) is not bytes
            ):
                raise RuntimeError(
                    "downstream HTTP response header is invalid"
                )
            copied_headers.append((bytes(header[0]), bytes(header[1])))
        for name, value in copied_headers:
            if name.lower() in {
                b"connection",
                b"keep-alive",
                b"proxy-authenticate",
                b"proxy-authorization",
                b"te",
                b"trailer",
                b"transfer-encoding",
                b"upgrade",
            }:
                raise RuntimeError(
                    "downstream HTTP response used a hop-by-hop header"
                )
            if name.lower() != b"content-length":
                continue
            try:
                content_length = int(value.decode("ascii"))
            except (UnicodeDecodeError, ValueError) as exc:
                raise RuntimeError(
                    "downstream HTTP response Content-Length is invalid"
                ) from exc
            if content_length < 0:
                raise RuntimeError(
                    "downstream HTTP response Content-Length is invalid"
                )
            if content_length > self.max_body_bytes:
                self.too_large = True
                raise RuntimeError(
                    "downstream HTTP response exceeds the signing bound"
                )
        self.status_code = status_code
        self.headers = copied_headers

    def _body(self, message: Message) -> None:
        if self.status_code is None:
            raise RuntimeError(
                "downstream HTTP response body preceded response start"
            )
        if self.complete:
            raise RuntimeError(
                "downstream HTTP response continued after completion"
            )
        chunk = message.get("body", b"")
        if type(chunk) is not bytes:
            raise RuntimeError("downstream HTTP response body is invalid")
        if len(chunk) > self.max_body_bytes - len(self.body):
            self.too_large = True
            self.body.clear()
            raise RuntimeError(
                "downstream HTTP response exceeds the signing bound"
            )
        more_body = message.get("more_body", False)
        if type(more_body) is not bool:
            raise RuntimeError(
                "downstream HTTP response continuation flag is invalid"
            )
        self.body.extend(chunk)
        if not more_body:
            self.complete = True


def _request_signature_inputs(
    scope: Scope,
) -> tuple[str, str, str, str | None, bool, bool]:
    method = scope.get("method")
    path = scope.get("path")
    query_string = scope.get("query_string", b"")
    raw_headers = scope.get("headers", [])
    if (
        not isinstance(method, str)
        or not isinstance(path, str)
        or type(query_string) is not bytes
        or not isinstance(raw_headers, list)
    ):
        raise RuntimeError("HTTP request ASGI scope is invalid")
    nonce = None
    invalid_nonce = False
    for header in raw_headers:
        if (
            not isinstance(header, tuple)
            or len(header) != 2
            or type(header[0]) is not bytes
            or type(header[1]) is not bytes
        ):
            raise RuntimeError("HTTP request ASGI headers are invalid")
        if header[0].lower() == b"x-serverware-response-nonce":
            if nonce is not None:
                invalid_nonce = True
                nonce = None
                continue
            if not invalid_nonce:
                nonce = header[1].decode("latin-1")
    if nonce is not None:
        try:
            nonce = validate_response_nonce(nonce)
        except ValueError:
            invalid_nonce = True
            nonce = None
    return (
        method,
        path,
        query_string.decode("latin-1"),
        nonce,
        scope.get("scheme") == "https",
        invalid_nonce,
    )


def _synthetic_signed_response_source(
    *, status_code: int, detail: str
) -> tuple[int, list[tuple[bytes, bytes]], bytes]:
    response = JSONResponse(
        status_code=status_code,
        content={"detail": detail},
    )
    return status_code, list(response.raw_headers), response.body


_SIGNED_RESPONSE_OWNED_HEADERS = frozenset(
    {
        b"cache-control",
        b"pragma",
        b"x-content-type-options",
        b"x-frame-options",
        b"referrer-policy",
        b"cross-origin-opener-policy",
        b"cross-origin-resource-policy",
        b"permissions-policy",
        b"content-security-policy",
        b"strict-transport-security",
    }
)


def _response_signer_owns_header(name: bytes) -> bool:
    lowered = name.lower()
    return (
        lowered in _SIGNED_RESPONSE_OWNED_HEADERS
        or lowered.startswith(b"x-serverware-response-")
    )


def _control_plane_security_headers(
    *, request_is_https: bool
) -> dict[str, str]:
    headers = {
        "Cache-Control": "no-store",
        "Pragma": "no-cache",
        "X-Content-Type-Options": "nosniff",
        "X-Frame-Options": "DENY",
        "Referrer-Policy": "no-referrer",
        "Cross-Origin-Opener-Policy": "same-origin",
        "Cross-Origin-Resource-Policy": "same-origin",
        "Permissions-Policy": (
            "camera=(), geolocation=(), microphone=(), payment=(), usb=(), "
            "publickey-credentials-create=(self), "
            "publickey-credentials-get=(self)"
        ),
        "Content-Security-Policy": (
            "default-src 'none'; base-uri 'none'; frame-ancestors 'none'; "
            "form-action 'self'; object-src 'none'; connect-src 'self'; "
            "img-src 'self' data:; font-src 'self'; "
            "style-src 'unsafe-inline'; script-src 'unsafe-inline'"
        ),
    }
    if request_is_https:
        headers["Strict-Transport-Security"] = (
            "max-age=31536000; includeSubDomains"
        )
    return headers


def _unsigned_wire_headers(
    *,
    source_headers: list[tuple[bytes, bytes]],
    request_is_https: bool,
    response_status_code: int,
    representation_body_length: int,
) -> list[tuple[bytes, bytes]]:
    preserved = [
        (name, value)
        for name, value in source_headers
        if name.lower() != b"content-length"
        and not _response_signer_owns_header(name)
    ]
    merged = list(preserved)
    if not (
        100 <= response_status_code < 200
        or response_status_code in {204, 304}
    ):
        merged.append(
            (
                b"content-length",
                str(representation_body_length).encode("ascii"),
            )
        )
    for name, value in _control_plane_security_headers(
        request_is_https=request_is_https
    ).items():
        merged.append((name.encode("ascii"), value.encode("latin-1")))
    return merged


def _proof_wire_headers(
    *,
    unsigned_headers: list[tuple[bytes, bytes]],
    proof_headers: dict[str, str],
) -> list[tuple[bytes, bytes]]:
    unsigned_names = {name.lower() for name, _value in unsigned_headers}
    result: list[tuple[bytes, bytes]] = []
    for name, value in proof_headers.items():
        encoded_name = name.encode("ascii")
        lowered = encoded_name.lower()
        if not lowered.startswith(b"x-serverware-response-"):
            raise RuntimeError(
                "response signer returned a non-proof header"
            )
        if lowered in unsigned_names:
            raise RuntimeError(
                "response proof header conflicts with an authenticated header"
            )
        result.append((encoded_name, value.encode("latin-1")))
    return result


class _SignedControlPlaneASGI:
    def __init__(self, application: ASGIApp) -> None:
        self.application = application

    def __getattr__(self, name: str) -> Any:
        return getattr(self.application, name)

    async def __call__(
        self,
        scope: Scope,
        receive: Receive,
        send: Send,
    ) -> None:
        if scope["type"] != "http":
            await self.application(scope, receive, send)
            return
        (
            request_method,
            request_path,
            request_query,
            request_nonce,
            request_is_https,
            invalid_request_nonce,
        ) = _request_signature_inputs(scope)
        acquired_buffer_slot = False
        try:
            try:
                await asyncio.wait_for(
                    _SIGNED_RESPONSE_BUFFER_SLOTS.acquire(),
                    timeout=_SIGNED_RESPONSE_BUFFER_ADMISSION_SECONDS,
                )
            except TimeoutError as exc:
                raise RuntimeError(
                    "signed response buffering capacity is unavailable"
                ) from exc
            acquired_buffer_slot = True
            buffered = _BufferedHttpResponse(
                max_body_bytes=_SIGNED_RESPONSE_MAX_BYTES
            )
            downstream_error: Exception | None = None
            if invalid_request_nonce:
                response_status_code, response_raw_headers, body = (
                    _synthetic_signed_response_source(
                        status_code=400,
                        detail="response nonce header is invalid or repeated",
                    )
                )
            else:
                try:
                    # This includes ServerErrorMiddleware and response background work.
                    await self.application(scope, receive, buffered.send)
                except asyncio.CancelledError:
                    raise
                except Exception as exc:
                    downstream_error = exc

            if not invalid_request_nonce and buffered.too_large:
                response_status_code, response_raw_headers, body = (
                    _synthetic_signed_response_source(
                        status_code=503,
                        detail="signed response exceeds 8 MiB",
                    )
                )
                downstream_error = None
            elif not invalid_request_nonce and downstream_error is not None:
                response_status_code, response_raw_headers, body = (
                    _synthetic_signed_response_source(
                        status_code=500,
                        detail="internal server error",
                    )
                )
            elif (
                not invalid_request_nonce
                and (buffered.status_code is None or not buffered.complete)
            ):
                downstream_error = RuntimeError(
                    "downstream HTTP response did not complete"
                )
                response_status_code, response_raw_headers, body = (
                    _synthetic_signed_response_source(
                        status_code=500,
                        detail="internal server error",
                    )
                )
            elif not invalid_request_nonce:
                response_status_code = buffered.status_code
                response_raw_headers = list(buffered.headers)
                body = bytes(buffered.body)
            buffered.body.clear()

            if (
                100 <= response_status_code < 200
                or (
                    response_status_code in {204, 205, 304}
                    and len(body) != 0
                )
            ):
                downstream_error = RuntimeError(
                    "downstream HTTP response used invalid no-body framing"
                )
                response_status_code, response_raw_headers, body = (
                    _synthetic_signed_response_source(
                        status_code=500,
                        detail="internal server error",
                    )
                )

            wire_body = b"" if request_method.upper() == "HEAD" else body
            unsigned_headers = _unsigned_wire_headers(
                source_headers=response_raw_headers,
                request_is_https=request_is_https,
                response_status_code=response_status_code,
                representation_body_length=len(body),
            )
            proof_headers: dict[str, str] = {}
            if request_nonce is not None:
                proof_headers = await _run_bounded_blocking(
                    _SIGNED_RESPONSE_WORKER_SLOTS,
                    _signed_control_plane_response_headers,
                    request_method=request_method,
                    request_path=request_path,
                    request_query=request_query,
                    request_nonce=request_nonce,
                    response_status_code=response_status_code,
                    response_headers=unsigned_headers,
                    body=wire_body,
                    representation_body=body,
                )
            response = Response(
                content=wire_body,
                status_code=response_status_code,
                media_type=None,
            )
            response.raw_headers = unsigned_headers + _proof_wire_headers(
                unsigned_headers=unsigned_headers,
                proof_headers=proof_headers,
            )
            from serverware import control_plane_oidc_session_activation_delivery as activation_delivery
            from serverware import control_plane_oidc_session_activation_recovery_delivery as recovery_delivery
            from serverware import control_plane_oidc_session_activation_completion_recovery_delivery_response as completion_delivery
            from serverware import control_plane_workload_identity_routes as workload_routes

            delivery = (workload_routes if scope.get("path") in workload_routes.PATHS
                else completion_delivery if scope.get("path") in completion_delivery.POST_PATHS
                else recovery_delivery if scope.get("path") == recovery_delivery.POST_PATH
                else activation_delivery)
            await delivery._send_response(scope, receive, send, response,
                before_dispatch=invalid_request_nonce,
                downstream_failed=downstream_error is not None or buffered.too_large or not buffered.complete)
            if downstream_error is not None:
                raise downstream_error
        finally:
            from serverware import control_plane_oidc_session_activation_delivery as activation_delivery
            from serverware import control_plane_oidc_session_activation_recovery_delivery as recovery_delivery
            from serverware import control_plane_oidc_session_activation_completion_recovery_delivery_response as completion_delivery
            from serverware import control_plane_workload_identity_routes as workload_routes

            workload_routes._discard_scope(scope)
            activation_delivery._discard_scope(scope)
            recovery_delivery._discard_scope(scope)
            completion_delivery._discard_scope(scope)
            if acquired_buffer_slot:
                _SIGNED_RESPONSE_BUFFER_SLOTS.release()


def _signed_control_plane_response_headers(
    *,
    request_method: str,
    request_path: str,
    request_query: str,
    request_nonce: str,
    response_status_code: int,
    response_headers: list[tuple[bytes, bytes]],
    body: bytes,
    representation_body: bytes | None = None,
) -> dict[str, str]:
    context_fields = (
        "runtime_manifest_digest",
        "policy_bundle_digest",
        "provenance_digest",
        "image_signatures_digest",
        "source_tree_digest",
    )
    if request_path == "/attestation" and response_status_code == 200:
        try:
            attestation = strict_json_loads(
                representation_body if representation_body is not None else body
            )
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise ValueError(
                "attestation representation is not strict JSON"
            ) from exc
        if not isinstance(attestation, dict) or any(
            field not in attestation for field in context_fields
        ):
            raise ValueError(
                "attestation representation is missing response-signature context"
            )
        context = {field: attestation[field] for field in context_fields}
    else:
        snapshot = get_policy_snapshot()
        context = {
            "runtime_manifest_digest": runtime_manifest_digest(),
            "policy_bundle_digest": snapshot.hash if snapshot else None,
            **attestation_artifact_digests(),
        }
    statement = response_statement(
        method=request_method,
        path=request_path,
        query=request_query,
        status_code=response_status_code,
        body=body,
        response_headers=response_headers,
        nonce=request_nonce,
        context=context,
    )
    return response_signature_headers(statement)


