    principal_id: str = Field(alias="principalId", min_length=1, max_length=1024)
    route_id: str = Field(alias="routeId", min_length=1, max_length=256)
    credential_ref: str | None = Field(
        alias="credentialRef", max_length=256
    )
    credential_version: int = Field(
        alias="credentialVersion",
        ge=0,
        le=18_446_744_073_709_551_615,
        strict=True,
    )
    policy_hash: str = Field(
        alias="policyHash", pattern=r"^sha256:[0-9a-f]{64}$"
    )
    request_digest: str = Field(
        alias="requestDigest", pattern=r"^sha256:[0-9a-f]{64}$"
    )
    operation_digest: str = Field(
        alias="operationDigest",
        pattern=r"^sha256:[0-9a-f]{64}$",
    )
    operation_context: dict[str, Any] = Field(
        alias="operationContext"
    )
    canonical_request: dict[str, Any] = Field(alias="canonicalRequest")
    durable_policy: DataPlaneReleaseAuthorizationDurablePolicyReserve | None = Field(
        default=None, alias="durablePolicy"
    )
    approver_policy_sha256: str | None = Field(
        default=None, alias="approverPolicySha256", pattern=r"^sha256:[0-9a-f]{64}$"
    )

    @model_validator(mode="after")
    def validate_canonical_payload_sizes(
        self,
    ) -> DataPlaneReleaseAuthorizationReserve:
        preparing = self.api_version in {
            "serverware.nativeReleaseAuthorizationPrepare/v1",
            "serverware.nativeReleaseAuthorizationPrepare/v2",
            "serverware.policyAwareReleaseAuthorizationPrepare/v1",
            "serverware.policyAwareReleaseAuthorizationPrepare/v2",
        }
        profile, durable = release_profiles.request_representation(
            self.api_version, "Prepare" if preparing else "Reserve"
        )
        if profile == "native":
            release_profiles.native_principal(self.principal_id)
        elif profile == "policy-aware":
            lease_profiles.policy_aware_identity(self.principal_id)
        elif len(self.principal_id) > 256:
            raise ValueError("legacy release principal exceeds 256 characters")
        base_fields = {
            "api_version",
            "attempt_id",
            "flow_id",
            "principal_id",
            "route_id",
            "credential_ref",
            "credential_version",
            "policy_hash",
            "request_digest",
            "operation_digest",
            "operation_context",
            "canonical_request",
        }
        expected_fields = (
            base_fields
            if not durable
            else base_fields | {"durable_policy"}
        )
        if profile != "legacy" and not preparing:
            expected_fields |= {"approver_policy_sha256"}
        if self.model_fields_set != expected_fields or (
            durable
            and self.durable_policy is None
        ) or (
            profile != "legacy" and not preparing and self.approver_policy_sha256 is None
        ):
            raise ValueError(
                "release authorization reserve fields do not match its version"
            )
        if self.durable_policy is not None and re.fullmatch(
            r"sha256:[0-9a-f]{64}", self.attempt_id
        ) is None:
            raise ValueError(
                "release authorization v2 attemptId must be a lowercase sha256 digest"
            )
        if not lease_profiles.text_matches(
            self.flow_id, self.attempt_id, native=profile == "native", policy_aware=profile == "policy-aware"
        ):
            raise ValueError("flowId must equal attemptId for atomic release authorization")
        _validate_credential_lease_operation_context(
            self.operation_context
        )
        for name, value in (
            ("operationContext", self.operation_context),
            ("canonicalRequest", self.canonical_request),
        ):
            try:
                encoded = json.dumps(
                    value,
                    sort_keys=True,
                    separators=(",", ":"),
                    ensure_ascii=True,
                    allow_nan=False,
                ).encode("utf-8")
            except (TypeError, ValueError) as exc:
                raise ValueError(f"{name} must be canonical JSON") from exc
            if len(encoded) > 64 * 1024:
                raise ValueError(f"{name} exceeds 64 KiB")
        return self


