@app.get("/api/auth/status")
def operator_auth_status(request: Request) -> dict[str, Any]:
    identity = None
    session = None
    token = request.cookies.get(OIDC_SESSION_COOKIE_NAME)
    if token:
        try:
            session = oidc_browser_session_for_request(request)
            if session is not None:
                identity = oidc_identity_from_browser_session(session)
        except (OIDCAuthError, OIDCAccessDenied, OIDCAuthoritativeStateError):
            identity = None
    return {
        "authenticated": identity is not None,
        "userId": identity.user_id if identity else None,
        "roles": sorted(identity.roles) if identity else [],
        "authMethod": identity.auth_method if identity else None,
        "sessionState": session.get("status") if session else None,
        "webauthnRequired": bool(
            session and session.get("status") == "pending_webauthn"
        ),
        "oidcBrowserLoginConfigured": browser_login_configured(),
    }


def _operator_oidc_source_key(request: Request) -> str:
    client = getattr(request, "client", None)
    peer_host = getattr(client, "host", None)
    try:
        canonical_peer = ipaddress.ip_address(str(peer_host)).compressed
    except ValueError:
        canonical_peer = "unknown"
    return (
        "sha256:"
        + hashlib.sha256(
            f"serverware-oidc-peer:{canonical_peer}".encode("ascii")
        ).hexdigest()
    )


def _operator_oidc_return_target(value: Any) -> str:
    if not isinstance(value, str):
        return "/"
    try:
        if len(value.encode("utf-8")) > _OIDC_RETURN_TARGET_MAX_BYTES:
            return "/"
    except UnicodeEncodeError:
        return "/"
    if (
        not value.startswith("/")
        or value.startswith("//")
        or "\\" in value
        or "%" in value
        or "#" in value
        or any(ord(character) < 32 or ord(character) == 127 for character in value)
    ):
        return "/"
    try:
        parsed = urlsplit(value)
    except ValueError:
        return "/"
    if parsed.scheme or parsed.netloc or parsed.fragment:
        return "/"
    if value in {"/", "/approvals"}:
        return value
    if not parsed.query and value == parsed.path:
        if _OIDC_APPROVAL_TARGET_RE.fullmatch(parsed.path):
            return parsed.path
        return "/"
    if parsed.path != "/" or not parsed.query or value.count("?") != 1:
        return "/"
    try:
        query = parse_qsl(
            parsed.query,
            keep_blank_values=True,
            strict_parsing=True,
            max_num_fields=2,
            separator="&",
        )
    except (UnicodeDecodeError, ValueError):
        return "/"
    if len(query) != 1 or query[0][0] != "setup":
        return "/"
    setup_id = query[0][1]
    if _OIDC_SETUP_TARGET_ID_RE.fullmatch(setup_id) is None:
        return "/"
    return "/?" + urlencode({"setup": setup_id})


def _operator_oidc_consumed_return_target(state_hash: str) -> str:
    cutoff = (
        datetime.now(timezone.utc)
        - timedelta(seconds=OIDC_LOGIN_STATE_TTL_SECONDS + 60)
    ).isoformat()
    try:
        result = db.search_audit_events(
            limit=2,
            scan_limit=5000,
            event_type="control_plane.oidc_login.started",
            start=cutoff,
            q=state_hash,
        )
    except (db.AuditStoreError, db.MetadataStoreError, ValueError):
        return "/"
    matches: list[str] = []
    for item in result.get("items", []):
        event = item.get("event")
        if not isinstance(event, dict):
            continue
        recorded_state_hash = event.get("state_hash")
        if not isinstance(recorded_state_hash, str) or not hmac.compare_digest(
            recorded_state_hash, state_hash
        ):
            continue
        target = event.get("return_target")
        if (
            not isinstance(target, str)
            or _operator_oidc_return_target(target) != target
        ):
            continue
        matches.append(target)
    return matches[0] if len(matches) == 1 else "/"


@app.get("/api/auth/oidc/start")
def operator_oidc_start(
    response: Response,
    request: Request,
    return_to: str | None = None,
) -> dict[str, Any]:
    return_target = _operator_oidc_return_target(return_to)
    source_key = _operator_oidc_source_key(request)
    try:
        with db.oidc_login_source(source_key):
            started = start_operator_login()
    except (OperatorOIDCError, db.MetadataStoreError, ValueError) as exc:
        detail = str(exc)
        status_code = (
            429 if "rate limit" in detail or "source capacity" in detail else 503
        )
        raise HTTPException(status_code=status_code, detail=detail) from exc
    response.set_cookie(
        "serverware_oidc_flow",
        started["browser_nonce"],
        max_age=OIDC_LOGIN_STATE_TTL_SECONDS,
        httponly=True,
        secure=request.url.scheme == "https",
        samesite="lax",
        path="/api/auth/oidc/callback",
    )
    db.record_audit_event(
        "control_plane.oidc_login.started",
        {
            "state_hash": started["state_hash"],
            "expires_at": started["expires_at"],
            "source_key": source_key,
            "return_target": return_target,
        },
    )
    return {
        "authorizationUrl": started["authorization_url"],
        "expiresAt": started["expires_at"],
    }


@app.get("/api/auth/oidc/callback")
def operator_oidc_callback(
    request: Request,
    state: str | None = None,
    code: str | None = None,
    error: str | None = None,
) -> Response:
    if error or not state or not code:
        raise HTTPException(
            status_code=400,
            detail="OIDC login was denied or returned an incomplete callback",
        )
    try:
        completed = complete_operator_login(
            state=state,
            code=code,
            browser_nonce=request.cookies.get("serverware_oidc_flow", ""),
        )
    except OperatorOIDCError as exc:
        raise HTTPException(status_code=401, detail=str(exc)) from exc
    identity = completed["identity"]
    state_hash = "sha256:" + hashlib.sha256(state.encode("ascii")).hexdigest()
    return_target = _operator_oidc_consumed_return_target(state_hash)
    response = RedirectResponse(url=return_target, status_code=303)
    response.set_cookie(
        OIDC_SESSION_COOKIE_NAME,
        completed["session_token"],
        max_age=completed["cookie_max_age"],
        httponly=True,
        secure=request.url.scheme == "https",
        samesite="strict",
        path="/",
    )
    response.delete_cookie("serverware_oidc_flow", path="/api/auth/oidc/callback")
    issue_csrf_cookie(response, request)
    db.record_audit_event(
        "control_plane.oidc_login.completed",
        {
            "user_id": identity.user_id,
            "roles": sorted(identity.roles),
            "expires_at_epoch": completed["expires_at"],
            "session_id": completed["session"]["id"],
            "session_status": completed["session"]["status"],
            "return_target": return_target,
        },
        actor_id=identity.user_id,
    )
    return response


def _oidc_session_for_request(request: Request, *, fresh: bool = False) -> tuple[str, dict[str, Any]]:
    token = request.cookies.get(OIDC_SESSION_COOKIE_NAME)
    try:
        session = (oidc_browser_session_from_token(token) if fresh
            else oidc_browser_session_for_request(request))
    except (OIDCAuthError, OIDCAuthoritativeStateError) as exc:
        raise HTTPException(status_code=503, detail=str(exc)) from exc
    if not token or not session:
        raise HTTPException(status_code=401, detail="OIDC browser session required")
    return token, session


def _pending_oidc_session_for_request(request: Request, *, fresh: bool = False) -> tuple[str, dict[str, Any]]:
    token, session = _oidc_session_for_request(request, fresh=fresh)
    if session.get("status") != "pending_webauthn":
        raise HTTPException(
            status_code=409, detail="OIDC browser session is not awaiting WebAuthn"
        )
    try:
        oidc_pending_session_identity(session)
    except OIDCAuthoritativeStateError as exc:
        raise HTTPException(status_code=503, detail=str(exc)) from exc
    except OIDCAccessDenied as exc:
        raise HTTPException(status_code=403, detail=str(exc)) from exc
    except OIDCAuthError as exc:
        raise HTTPException(status_code=401, detail=str(exc)) from exc
    return token, session


@app.post("/api/auth/session/webauthn/options")
def operator_session_webauthn_options(request: Request) -> dict[str, Any]:
    _require_registration_execution_session_csrf(request)
    _, session = _pending_oidc_session_for_request(request, fresh=True)
    try:
        options = oidc_session_binding_options(
            session_id=str(session["id"]),
            user_id=str(session["user_id"]),
            session_expires_at=str(session["expires_at"]),
            pending_expires_at=str(session["pending_expires_at"]),
            authn_policy=_control_plane_mutation_authn_policy(),
            ttl_seconds=OIDC_SESSION_WEBAUTHN_CHALLENGE_TTL_SECONDS,
        )
    except WebAuthnError as exc:
        if "no currently eligible WebAuthn credential" not in str(exc):
            raise HTTPException(status_code=409, detail=str(exc)) from exc
        history = db.list_webauthn_credentials(
            str(session["user_id"]), include_revoked=True
        )
        active_credential_count = sum(
            1 for credential in history if credential.get("revoked_at") is None
        )
        raise HTTPException(
            status_code=409,
            detail={
                "error": "oidc_session_webauthn_unavailable",
                "message": "No currently trusted passkey is registered for this OIDC subject",
                "firstEnrollmentAvailable": not history,
                "recoveryAvailable": bool(history)
                and active_credential_count == 0
                and WEBAUTHN_RECOVERY_ENABLED,
                "offlineRevocationAvailable": active_credential_count == 1
                and WEBAUTHN_RECOVERY_ENABLED,
                "bootstrapRequired": RELEASE_CHANNEL.strip().lower()
                not in {"dev", "development", "local", "test"},
            },
        )
    return options


def _oidc_first_enrollment_authorization(
    session: dict[str, Any], payload_digest: str
) -> dict[str, Any]:
    return {
        "mode": "oidc-session-first-enrollment",
        "session_id": session["id"],
        "user_id": session["user_id"],
        "pending_expires_at": session["pending_expires_at"],
        "payload_digest": payload_digest,
        "existing_credential_count": 0,
    }


def _operator_registration_originals(
    *, label: str, response: dict[str, Any], identity: AdminIdentity,
) -> _RegistrationOriginals:
    """Capture finish inputs after the real operator authentication dependency.

    Only the actual authenticated handler supplies this identity, after its
    admin/approver role dependency and normal CSRF middleware. The live
    challenge retains the enrollment authorization established at options;
    this read-only capture neither reruns nor consumes MFA or approvals.
    Returned original bytes/scope are not an authentication or membership
    proof and cannot substitute for the real registration continuation.
    """
    user_id = identity.user_id
    held_label, held_response = label, response
    return _capture_registration_originals(user_id, held_label, held_response,
        require_authorization=True)


def _oidc_registration_originals(
    *, label: str, response: dict[str, Any], session: dict[str, Any],
) -> _RegistrationOriginals:
    """Capture finish inputs from the handler's genuinely admitted live session.

    The handler must first call _pending_oidc_session_for_request, preserving
    real cookie/session lookup and current authoritative RBAC admission. This
    parameter is not a browser-supplied session or a transferable authority
    carrier. All identity/scope scalars are held before canonical hashing or
    input-capture callbacks; the existing six-field authorization recipe is
    joined to the actual unused challenge without activating the session.
    """
    session_id, user_id, pending_expires_at = (
        session["id"], session["user_id"], session["pending_expires_at"])
    held_label, held_response = label, response
    held_session = {"id": session_id, "user_id": user_id,
        "pending_expires_at": pending_expires_at}
    payload_digest = _control_plane_payload_digest({
        "type": "serverware.oidc_session_first_enrollment",
        "session_id": session_id, "user_id": user_id,
        "pending_expires_at": pending_expires_at, "label": held_label})
    expected = _oidc_first_enrollment_authorization(held_session, payload_digest)
    return _capture_registration_originals(str(user_id), held_label, held_response,
        require_authorization=True, expected_authorization=expected)


def _registration_preparation_error(status_code: int, error: str) -> JSONResponse:
    return JSONResponse(status_code=status_code,
        headers={"Cache-Control": "no-store", "Pragma": "no-cache",
            "X-Content-Type-Options": "nosniff"},
        content={"detail": {"error": error, "registrationCompleted": False,
            "remoteState": "unknown"}})


def _registration_execution_preparation_error(status_code: int, error: str) -> JSONResponse:
    return JSONResponse(status_code=status_code,
        headers={"Cache-Control": "no-store", "Pragma": "no-cache",
            "X-Content-Type-Options": "nosniff"},
        content={"detail": {"error": error, "registrationCompleted": False,
            "executionStarted": False, "remoteState": "unknown"}})


def _registration_execution_preparation_payload(request: Request) -> WebAuthnRegistrationExecutionPrepare:
    payload = getattr(request.state, "registration_execution_preparation_payload", None)
    if type(payload) is not WebAuthnRegistrationExecutionPrepare:
        raise HTTPException(status_code=400, detail="execution preparation framing is required",
            headers={"Cache-Control": "no-store", "Pragma": "no-cache"})
    return payload


def _registration_reservation_error(status_code: int, error: str, *, local_digest=None) -> JSONResponse:
    from serverware import control_plane_registration_reservation_status as projection

    try:
        detail = projection.unavailable(local_digest)
    except ValueError:
        detail = projection.unavailable()
    detail["error"] = error
    return JSONResponse(status_code=status_code,
        headers={"Cache-Control": "no-store", "Pragma": "no-cache",
            "X-Content-Type-Options": "nosniff"}, content={"detail": detail})


def _registration_reservation_payload(request: Request) -> WebAuthnRegistrationReservation:
    payload = getattr(request.state, "registration_reservation_payload", None)
    if type(payload) is not WebAuthnRegistrationReservation:
        raise HTTPException(status_code=400, detail="reservation framing is required",
            headers={"Cache-Control": "no-store", "Pragma": "no-cache"})
    return payload


def _registration_execution_owner():
    """Check opt-in cold scope before spending MFA or approval authority."""
    from serverware import control_plane_enrollment_startup as enrollment

    owner = enrollment.require_started()
    if type(owner) is not enrollment._EnrollmentOwner or not owner.execution_enabled:
        raise HTTPException(status_code=503, detail="registration execution preparation is not enabled")
    return owner


def _registration_reservation_owner():
    owner = _registration_execution_owner()
    if not owner.reservation_enabled:
        raise HTTPException(status_code=503, detail="registration reservation is not enabled")
    return owner


def _require_registration_execution_bootstrap(token: str | None) -> None:
    # This is a fresh independent presentation for the NEW purpose. Unlike
    # legacy options, this route has no development-bootstrap bypass.
    if len(WEBAUTHN_BOOTSTRAP_TOKEN) < 32:
        raise HTTPException(status_code=503, detail="registration execution bootstrap is not configured safely")
    if token is None or not hmac.compare_digest(
            WEBAUTHN_BOOTSTRAP_TOKEN.encode("utf-8"), token.encode("utf-8")):
        raise HTTPException(status_code=403, detail="fresh bootstrap authorization is required for execution preparation")


def _registration_execution_current_operator(request: Request, expected: AdminIdentity) -> AdminIdentity:
    # Explicitly repeat real request authentication and current authoritative
    # role lookup after assertion/approval work, not an identity DTO check.
    current = require_admin(request,
        x_serverware_admin_token=request.headers.get("X-Serverware-Admin-Token"))
    if current.auth_method == "oidc-session":
        # require_admin may have reused this request's session cache. The
        # uncached path repeats DB-time expiry/revocation, bound-credential and
        # current trust checks, not merely the cached identity's RBAC lookup.
        try:
            current = oidc_identity_from_session_token(request.cookies.get(OIDC_SESSION_COOKIE_NAME))
        except OIDCAuthoritativeStateError:
            raise HTTPException(status_code=503, detail="registration preparation session state unavailable") from None
        except OIDCAccessDenied:
            raise HTTPException(status_code=403, detail="registration preparation session access denied") from None
        except OIDCAuthError:
            raise HTTPException(status_code=401, detail="registration preparation session is no longer valid") from None
        if current is None:
            raise HTTPException(status_code=401, detail="registration preparation session is required")
    current = require_role("admin", "approver")(current)
    if (current.user_id, current.auth_method) != (expected.user_id, expected.auth_method):
        raise HTTPException(status_code=409, detail="registration preparation caller changed")
    return current


def _require_registration_execution_session_csrf(request: Request) -> None:
    # This route always acts as the pending COOKIE subject. An unrelated valid
    # bearer/admin header must not select the global middleware's CSRF bypass.
    cookie = request.cookies.get(CSRF_COOKIE_NAME)
    headers = request.headers.getlist(CSRF_HEADER_NAME)
    if (not cookie or len(cookie) > 1024 or len(headers) != 1
            or not headers[0] or len(headers[0]) > 1024
            or not hmac.compare_digest(cookie.encode("utf-8"), headers[0].encode("utf-8"))):
        raise HTTPException(status_code=403, detail="CSRF token required for pending-session action")


def _require_registration_execution_bootstrap_branch(
    payload: WebAuthnRegistrationExecutionPrepare | WebAuthnRegistrationReservation,
) -> None:
    if payload.mfa is not None:
        raise HTTPException(status_code=400, detail="first enrollment requires bootstrap authorization, not mfa")
    _require_registration_execution_bootstrap(payload.bootstrap_token)


def _require_registration_execution_existing_authorization(
    *, originals: _RegistrationOriginals,
    payload: WebAuthnRegistrationExecutionPrepare | WebAuthnRegistrationReservation,
    identity: AdminIdentity, reservation: bool = False,
) -> None:
    if type(reservation) is not bool or type(payload) is not (
            WebAuthnRegistrationReservation if reservation else WebAuthnRegistrationExecutionPrepare):
        raise HTTPException(status_code=400, detail="registration action payload differs")
    if reservation:
        from serverware import control_plane_registration_reservation_intent as intent
    else:
        from serverware import control_plane_registration_execution_intent as intent

    if payload.bootstrap_token is not None:
        raise HTTPException(status_code=400, detail="bootstrap authorization cannot replace existing-credential authorization")
    binding = intent.request_binding(originals)
    digest = _control_plane_payload_digest(binding)
    resource_id = binding["challengeId"]
    mfa = payload.mfa.model_dump(by_alias=True, exclude_none=True) if payload.mfa is not None else None
    assertion = mfa.get("assertion") if mfa is not None else None
    if not assertion:
        raise HTTPException(status_code=412, detail={
            "error": "control_plane_webauthn_required",
            "message": ("Fresh WebAuthn assertion required for registration reservation" if reservation
                else "Fresh WebAuthn assertion required for registration execution preparation"),
            "action": intent.ACTION, "resourceId": resource_id, "payloadDigest": digest})
    # Do not use the generic helper's authority-evidence shortcut, or its
    # development opt-out. Successful actual local verification is required.
    try:
        verify_control_plane_mutation_assertion(user_id=identity.user_id,
            action=intent.ACTION, resource_id=resource_id, payload_digest=digest,
            authn_policy=_control_plane_mutation_authn_policy(), assertion=assertion)
    except WebAuthnError:
        raise HTTPException(status_code=403, detail="registration execution MFA authorization was denied") from None
    _require_control_plane_two_person(action=intent.ACTION, resource_id=resource_id,
        payload_digest=digest, mfa=mfa, identity=identity, request=binding)


def _registration_execution_prepared_response(originals: _RegistrationOriginals, owner) -> JSONResponse:
    """Called only after this handler's real current new-purpose admission."""
    from serverware import control_plane_registration_preparation as preparation
    from serverware import control_plane_registration_execution_intent as intent

    if _registration_execution_owner() is not owner:
        raise HTTPException(status_code=503, detail="registration execution owner changed")
    try:
        local_digest = preparation.prepare_and_retain_registration_execution_grant(originals)
        if type(local_digest) is not str or re.fullmatch(r"sha256:[0-9a-f]{64}", local_digest) is None:
            raise ValueError("execution preparation did not return its local identity")
    except Exception:
        # Approval, signer authority or durable storage can precede failure.
        # Reveal no originals or internal text, and never authorize a retry.
        return _registration_execution_preparation_error(503, "registration_execution_preparation_unavailable")
    return JSONResponse(status_code=202,
        headers={"Cache-Control": "no-store", "Pragma": "no-cache",
            "X-Content-Type-Options": "nosniff"},
        content={"schema": "serverware.webAuthnRegistrationExecutionPreparation/v1",
            "status": "retained-execution-grant", "purpose": intent.PURPOSE,
            "localDigest": local_digest, "registrationCompleted": False,
            "executionStarted": False})


def _registration_reserved_response(originals: _RegistrationOriginals, owner) -> JSONResponse:
    """After real reserve-purpose admission; never SQL or session activation."""
    from serverware import control_plane_registration_preparation as preparation
    from serverware import control_plane_registration_reservation_status as projection

    if _registration_reservation_owner() is not owner:
        raise HTTPException(status_code=503, detail="registration reservation owner changed")
    try:
        local_digest, raw3 = preparation.prepare_and_reserve_registration_execution(originals)
        content = projection.accepted(local_digest, raw3)
    except preparation.RegistrationReservationOutcomeError as exc:
        # Only the actual facade's typed post-retention failure supplies this
        # confirmed local locator; arbitrary exception attributes never do.
        return _registration_reservation_error(503, "registration_reservation_unavailable",
            local_digest=exc.local_digest)
    except Exception:
        return _registration_reservation_error(503, "registration_reservation_unavailable")
    return JSONResponse(status_code=202,
        headers={"Cache-Control": "no-store", "Pragma": "no-cache",
            "X-Content-Type-Options": "nosniff"}, content=content)


def _registration_reservation_http_error(exc: HTTPException) -> JSONResponse:
    # Preserve existing bounded MFA/approval negotiation, never internal 5xx
    # exception text or a claim that remote reservation did not happen.
    if exc.status_code >= 500:
        return _registration_reservation_error(503, "registration_reservation_unavailable")
    detail = exc.detail
    if type(detail) is dict:
        detail = {key: value for key, value in detail.items() if key != "retry"}
        detail["automaticRetryAllowed"] = False
    return JSONResponse(status_code=exc.status_code,
        headers={**(exc.headers or {}), "Cache-Control": "no-store", "Pragma": "no-cache",
            "X-Content-Type-Options": "nosniff"}, content={"detail": detail})


def _registration_preparation_payload(request: Request) -> WebAuthnRegistrationPrepare:
    payload = getattr(request.state, "registration_preparation_payload", None)
    if type(payload) is not WebAuthnRegistrationPrepare:
        raise HTTPException(status_code=400, detail="registration preparation framing is required",
            headers={"Cache-Control": "no-store", "Pragma": "no-cache"})
    return payload


def _registration_custody_prepared_response(originals: _RegistrationOriginals) -> JSONResponse:
    """Append locally through the fixed continuation; never forward or finalize."""
    try:
        from serverware import control_plane_registration_preparation as preparation

        local_digest = preparation.prepare_registration_custody(originals)
        if type(local_digest) is not str or re.fullmatch(r"sha256:[0-9a-f]{64}", local_digest) is None:
            raise ValueError("registration preparation did not return its local identity")
    except Exception:
        # A spent grant or local durable write can precede a failure. No error
        # body exposes originals/internal text or asserts remote absence/retry.
        return _registration_preparation_error(503, "registration_preparation_unavailable")
    return JSONResponse(status_code=202,
        headers={"Cache-Control": "no-store", "Pragma": "no-cache",
            "X-Content-Type-Options": "nosniff"},
        content={"schema": "serverware.webAuthnRegistrationCustodyPreparation/v1",
            "status": "prepared", "localDigest": local_digest,
            "registrationCompleted": False})


@app.post("/api/auth/session/webauthn/register/prepare", status_code=202)
def operator_session_webauthn_register_prepare(
    request: Request,
    payload: WebAuthnRegistrationPrepare = Depends(_registration_preparation_payload),
) -> JSONResponse:
    # Actual pending-session lookup includes current authoritative OIDC RBAC;
    # normal cookie CSRF middleware still applies. No session is activated here.
    _, session = _pending_oidc_session_for_request(request)
    label, response = payload.label, payload.response
    try:
        with trust_bundle_lock(exclusive=False):
            originals = _oidc_registration_originals(label=label, response=response, session=session)
            return _registration_custody_prepared_response(originals)
    except WebAuthnError:
        return _registration_preparation_error(400, "registration_preparation_originals_invalid")
    except Exception:
        return _registration_preparation_error(503, "registration_preparation_unavailable")


@app.post("/api/auth/session/webauthn/register/prepare-execution", status_code=202)
def operator_session_webauthn_register_prepare_execution(
    request: Request,
    payload: WebAuthnRegistrationExecutionPrepare = Depends(_registration_execution_preparation_payload),
) -> JSONResponse:
    try:
        _require_registration_execution_session_csrf(request)
        _, session = _pending_oidc_session_for_request(request, fresh=True)
        owner = _registration_execution_owner()
        with trust_bundle_lock(exclusive=False):
            user_id = str(session["user_id"])
            if db.list_webauthn_credentials(user_id, include_revoked=True):
                raise HTTPException(status_code=409, detail="first enrollment is closed because credential history exists")
            _require_registration_execution_bootstrap_branch(payload)
            # Snapshot actual DB/session scope before original capture. Repeat
            # uncached session/RBAC and empty-history admission before signing.
            session_fields = ("id", "user_id", "expires_at", "pending_expires_at")
            held_scope = tuple(session[field] for field in session_fields)
            held_roles = frozenset(session["roles"])
            originals = _oidc_registration_originals(
                label=payload.label, response=payload.response, session=session)
            _, current = _pending_oidc_session_for_request(request, fresh=True)
            if (tuple(current[field] for field in session_fields) != held_scope
                    or frozenset(current["roles"]) != held_roles):
                raise HTTPException(status_code=409, detail="registration preparation session changed")
            if db.list_webauthn_credentials(user_id, include_revoked=True):
                raise HTTPException(status_code=409, detail="first enrollment is closed because credential history exists")
            return _registration_execution_prepared_response(originals, owner)
    except HTTPException:
        raise
    except WebAuthnError:
        return _registration_execution_preparation_error(400, "registration_execution_originals_invalid")
    except Exception:
        return _registration_execution_preparation_error(503, "registration_execution_preparation_unavailable")


@app.post("/api/auth/session/webauthn/register/reserve-execution", status_code=202)
def operator_session_webauthn_register_reserve_execution(
    request: Request,
    payload: WebAuthnRegistrationReservation = Depends(_registration_reservation_payload),
) -> JSONResponse:
    try:
        _require_registration_execution_session_csrf(request)
        _, session = _pending_oidc_session_for_request(request, fresh=True)
        owner = _registration_reservation_owner()
        with trust_bundle_lock(exclusive=False):
            user_id = str(session["user_id"])
            if db.list_webauthn_credentials(user_id, include_revoked=True):
                raise HTTPException(status_code=409, detail="first enrollment is closed because credential history exists")
            _require_registration_execution_bootstrap_branch(payload)
            session_fields = ("id", "user_id", "expires_at", "pending_expires_at")
            held_scope = tuple(session[field] for field in session_fields)
            held_roles = frozenset(session["roles"])
            originals = _oidc_registration_originals(
                label=payload.label, response=payload.response, session=session)
            _, current = _pending_oidc_session_for_request(request, fresh=True)
            if (tuple(current[field] for field in session_fields) != held_scope
                    or frozenset(current["roles"]) != held_roles):
                raise HTTPException(status_code=409, detail="registration reservation session changed")
            if db.list_webauthn_credentials(user_id, include_revoked=True):
                raise HTTPException(status_code=409, detail="first enrollment is closed because credential history exists")
            # This explicit reserve action does not activate the pending
            # session, finalize credentials or run a protected SQL effect.
            return _registration_reserved_response(originals, owner)
    except HTTPException as exc:
        return _registration_reservation_http_error(exc)
    except WebAuthnError:
        return _registration_reservation_error(400, "registration_reservation_originals_invalid")
    except Exception:
        return _registration_reservation_error(503, "registration_reservation_unavailable")


@app.post("/api/auth/session/webauthn/register/options")
def operator_session_webauthn_register_options(
    payload: WebAuthnRegistrationStart, request: Request
) -> dict[str, Any]:
    _, session = _pending_oidc_session_for_request(request)
    history = db.list_webauthn_credentials(
        str(session["user_id"]), include_revoked=True
    )
    if history:
        raise HTTPException(
            status_code=409,
            detail="first enrollment is closed because credential history exists",
        )
    production_release = RELEASE_CHANNEL.strip().lower() not in {
        "dev",
        "development",
        "local",
        "test",
    }
    if production_release:
        if len(WEBAUTHN_BOOTSTRAP_TOKEN) < 32:
            raise HTTPException(
                status_code=503, detail="WebAuthn bootstrap token is not configured safely"
            )
        if not payload.bootstrap_token or not hmac.compare_digest(
            WEBAUTHN_BOOTSTRAP_TOKEN, payload.bootstrap_token
        ):
            raise HTTPException(
                status_code=403,
                detail="valid WebAuthn bootstrap token required for first enrollment",
            )
    payload_digest = _control_plane_payload_digest(
        {
            "type": "serverware.oidc_session_first_enrollment",
            "session_id": session["id"],
            "user_id": session["user_id"],
            "pending_expires_at": session["pending_expires_at"],
            "label": payload.label,
        }
    )
    return registration_options(
        str(session["user_id"]),
        payload.label,
        authorization=_oidc_first_enrollment_authorization(
            session, payload_digest
        ),
    )


@app.post("/api/auth/session/webauthn/register/verify")
def operator_session_webauthn_register_verify(
    payload: WebAuthnRegistrationFinish, request: Request
) -> dict[str, Any]:
    _, session = _pending_oidc_session_for_request(request)
    label, response = payload.label, payload.response
    try:
        with trust_bundle_lock(exclusive=False):
            originals = _oidc_registration_originals(
                label=label, response=response, session=session)
            credential = _verify_registration_originals(originals,
                require_authorization=True)
    except WebAuthnError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    credential.pop("_registration_authorization", None)
    return credential


def _recovery_http_exception(exc: WebAuthnError) -> HTTPException:
    detail = str(exc)
    normalized = detail.lower()
    if any(
        marker in normalized
        for marker in (
            "trust bundle",
            "trust publication",
            "recovery root",
            "recovery is disabled",
            "metadata",
        )
    ):
        return HTTPException(status_code=503, detail=detail)
    if any(
        marker in normalized
        for marker in (
            "signature",
            "authorization",
            "hardware attestation",
            "subject mismatch",
        )
    ):
        return HTTPException(status_code=403, detail=detail)
    if any(
        marker in normalized
        for marker in (
            "history",
            "active webauthn",
            "ordinary webauthn",
            "state changed",
            "already",
            "not live",
            "not prepared",
            "not awaiting",
            "expired",
            "replayed",
            "capacity",
        )
    ):
        return HTTPException(status_code=409, detail=detail)
    return HTTPException(status_code=400, detail=detail)


def _webauthn_recovery_policy_digest() -> str:
    return _control_plane_payload_digest(_control_plane_mutation_authn_policy())


