@app.post("/api/auth/session/webauthn/verify")
def operator_session_webauthn_verify(
    payload: OIDCSessionWebAuthnVerify, request: Request, response: Response
) -> dict[str, Any]:
    # This action always uses the browser cookie, even when another valid
    # authentication header would bypass generic middleware CSRF admission.
    _require_registration_execution_session_csrf(request)
    try:
        assertion_binding = oidc_session_assertion_binding(payload.response)
    except WebAuthnError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    token = request.cookies.get(OIDC_SESSION_COOKIE_NAME)
    if not token:
        raise HTTPException(status_code=401, detail="OIDC browser session required")
    try:
        session = oidc_browser_session_from_token(token)
    except OIDCAuthoritativeStateError as exc:
        raise HTTPException(status_code=503, detail="OIDC browser session state is unavailable") from exc
    except OIDCAuthError as exc:
        raise HTTPException(status_code=401, detail=str(exc)) from exc
    if session is not None and session.get("status") == "pending_webauthn":
        _, session = _pending_oidc_session_for_request(request, fresh=True)
        active_token = secrets.token_urlsafe(48)
        try:
            evidence = verify_oidc_session_binding_assertion(
                old_token_digest=oidc_session_token_digest(token),
                new_token_digest=oidc_session_token_digest(active_token),
                session_id=str(session["id"]),
                user_id=str(session["user_id"]),
                session_expires_at=str(session["expires_at"]),
                pending_expires_at=str(session["pending_expires_at"]),
                authn_policy=_control_plane_mutation_authn_policy(),
                assertion=payload.response,
                encrypted_active_token=encrypt_secret(active_token),
            )
        except WebAuthnError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
    elif session is None:
        try:
            delivery = db.recover_oidc_session_activation_delivery(
                old_token_digest=oidc_session_token_digest(token),
                assertion_digest=assertion_binding["assertion_digest"],
                challenge=assertion_binding["challenge"],
            )
        except db.MetadataStoreError as exc:
            raise HTTPException(status_code=503, detail=str(exc)) from exc
        if not delivery.get("ok"):
            raise HTTPException(
                status_code=409,
                detail="OIDC session activation retry is unavailable",
            )
        try:
            active_token = decrypt_secret(str(delivery["encrypted_active_token"]))
        except (TypeError, ValueError) as exc:
            raise HTTPException(
                status_code=503,
                detail="OIDC session activation retry envelope is invalid",
            ) from exc
        evidence = {"session": delivery["session"]}
    else:
        raise HTTPException(
            status_code=409, detail="OIDC browser session is not awaiting WebAuthn"
        )
    # A committed transaction or retained delivery does not override current
    # credential trust or authoritative roles. Re-read the rotated session and
    # admit its actual active identity before releasing its cookie. This is a
    # local delivery check, not external currentness or protected F08 execution.
    try:
        active_session = oidc_browser_session_from_token(active_token)
        active_identity = (None if active_session is None
            else oidc_identity_from_browser_session(active_session))
        if (active_identity is None
                or active_identity.auth_method != "oidc-session"
                or active_identity.user_id != evidence["session"]["user_id"]
                or active_session["id"] != evidence["session"]["id"]
                or active_session.get("bound_webauthn_credential_id")
                    != evidence["session"].get("bound_webauthn_credential_id")):
            raise OIDCAuthError("OIDC browser session delivery scope changed")
    except (OIDCAuthError, OIDCAccessDenied, OIDCAuthoritativeStateError) as exc:
        raise HTTPException(status_code=503, detail={
            "error": "oidc_session_activation_delivery_unavailable",
            "message": "Activation may have committed; current session delivery is unavailable",
            "automaticRetryAllowed": False,
        }) from exc
    active_expires_at = datetime.fromisoformat(str(active_session["expires_at"]))
    active_max_age = max(
        1, int((active_expires_at - datetime.now(timezone.utc)).total_seconds())
    )
    response.set_cookie(
        OIDC_SESSION_COOKIE_NAME,
        active_token,
        max_age=active_max_age,
        httponly=True,
        secure=request.url.scheme == "https",
        samesite="strict",
        path="/",
    )
    return {"ok": True, "authenticated": True}


@app.post("/api/auth/logout")
def operator_logout(
    response: Response,
    request: Request,
    x_serverware_admin_token: str | None = Header(
        default=None, alias="X-Serverware-Admin-Token"
    ),
) -> dict[str, Any]:
    session_token = request.cookies.get(OIDC_SESSION_COOKIE_NAME)
    session = None
    try:
        identity = require_admin(request, x_serverware_admin_token)
    except HTTPException as exc:
        if exc.status_code != 401:
            raise
        _, session = _oidc_session_for_request(request)
        identity = AdminIdentity(
            str(session["user_id"]),
            frozenset(str(role) for role in session.get("roles", [])),
            "oidc-session-pending",
        )
    if session_token:
        result = db.revoke_oidc_browser_session(
            token_digest=oidc_session_token_digest(session_token),
            actor_id=identity.user_id,
            reason="operator_logout",
        )
        session = session or result.get("session")
    response.delete_cookie(
        OIDC_SESSION_COOKIE_NAME,
        path="/",
        secure=request.url.scheme == "https",
        httponly=True,
        samesite="strict",
    )
    response.delete_cookie(CSRF_COOKIE_NAME, path="/")
    db.record_audit_event(
        "control_plane.logout",
        {
            "auth_method": identity.auth_method,
            "session_id": session.get("id") if session else None,
        },
        actor_id=identity.user_id,
    )
    return {"ok": True}


def _approval_jit_policy(
    approval: dict[str, Any], *, require_current_policy: bool = False
) -> dict[str, Any]:
    snapshot = get_policy_snapshot()
    if not snapshot:
        raise HTTPException(status_code=503, detail="policy bundle missing")
    if require_current_policy and snapshot.hash != approval.get("policy_hash"):
        raise HTTPException(
            status_code=409,
            detail="active policy changed after approval request; request a new approval",
        )
    route = _active_route_by_id(str(approval.get("route_id") or ""), snapshot=snapshot)
    return route.jit or {}


def _active_route_by_id(route_id: str, *, snapshot: Any | None = None) -> Any:
    snapshot = snapshot or get_policy_snapshot()
    if not snapshot:
        raise HTTPException(status_code=503, detail="policy bundle missing")
    route = next((item for item in snapshot.routes if item.id == route_id), None)
    if not route:
        raise HTTPException(
            status_code=409, detail="approval route is not in the active policy"
        )
    return route


def _approval_authn_policy(jit: dict[str, Any]) -> dict[str, Any]:
    return (jit.get("approvers") or {}).get("authn") or {}


def _jit_approve_authority_arguments(
    *,
    approval: dict[str, Any],
    actor_id: str,
    ttl_seconds: int,
    review_receipt: dict[str, Any],
    note: str | None,
) -> dict[str, Any]:
    policy = approval.get("approver_policy")
    if not isinstance(policy, dict):
        raise HTTPException(
            status_code=409,
            detail="approval approver policy binding is unavailable",
        )
    allowed_ids = (
        None
        if policy.get("allowAnyApproverId") is True
        else set(policy.get("allowedApproverIds") or [])
    )
    credential_policy = policy.get("credentialPolicy")
    if (
        not isinstance(credential_policy, dict)
        or not isinstance(policy.get("threshold"), int)
    ):
        raise HTTPException(
            status_code=409,
            detail="approval approver policy binding is invalid",
        )
    return {
        "item_id": approval["id"],
        "ttl_seconds": ttl_seconds,
        "note": note,
        "actor_id": actor_id,
        "review_receipt_id": review_receipt["id"],
        "review_digest": review_receipt["review_digest"],
        "require_review_receipt": True,
        "required_approver_roles":
            set(policy.get("requiredRoles") or []),
        "authority_policy_hash":
            str(approval.get("policy_hash") or ""),
        "authority_route_id":
            str(approval.get("route_id") or ""),
        "allowed_approver_ids": allowed_ids,
        "require_approver_webauthn":
            policy.get("requireWebAuthn") is True,
        "approval_threshold": int(policy["threshold"]),
        "approver_credential_policy": credential_policy,
    }


def _assert_approver_allowed(identity: AdminIdentity, jit: dict[str, Any]) -> None:
    approvers = jit.get("approvers") or {}
    users = set(approvers.get("users") or [])
    if identity.user_id not in users:
        raise HTTPException(
            status_code=403,
            detail="current user is not an allowed approver for this route",
        )


def _approval_review_authority_metadata(approval_id: str) -> dict[str, Any] | None:
    with db.connect() as conn:
        row = conn.execute(
            """
            SELECT id, route_id, method, url, status, requested_at, expires_at,
                   approved_until, decision_note, principal_id, credential_id,
                   credential_version, policy_hash, request_digest,
                   operation_digest, grant_ttl_seconds, grant_max_uses,
                   approved_by
            FROM approval_requests
            WHERE id = ?
            """,
            (approval_id,),
        ).fetchone()
    return db.approval_public_summary(dict(row)) if row else None


def _assert_approval_reviewer_allowed(
    identity: AdminIdentity, approval: dict[str, Any]
) -> None:
    if not identity.has_any_role({"approver"}):
        raise HTTPException(status_code=403, detail="required role: approver")
    jit = _approval_jit_policy(approval, require_current_policy=True)
    _assert_approver_allowed(identity, jit)


def _webauthn_required(authn_policy: dict[str, Any]) -> bool:
    return bool(authn_policy.get("webauthnRequired"))


def _canonical_json(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=True)


def _decode_unpadded_base64url(
    value: str, *, field_name: str, expected_length: int
) -> bytes:
    if "=" in value or not re.fullmatch(r"[A-Za-z0-9_-]+", value):
        raise HTTPException(
            status_code=400, detail=f"{field_name} must be unpadded base64url"
        )
    try:
        decoded = base64.b64decode(
            value + "=" * (-len(value) % 4), altchars=b"-_", validate=True
        )
    except ValueError as exc:
        raise HTTPException(
            status_code=400, detail=f"{field_name} must be unpadded base64url"
        ) from exc
    if len(decoded) != expected_length:
        raise HTTPException(
            status_code=400,
            detail=f"{field_name} must decode to exactly {expected_length} bytes",
        )
    if not hmac.compare_digest(
        base64.urlsafe_b64encode(decoded).decode("ascii").rstrip("="), value
    ):
        raise HTTPException(
            status_code=400,
            detail=f"{field_name} must use canonical base64url encoding",
        )
    return decoded


async def _bounded_exact_data_plane_model(
    request: Request,
    *,
    model_type: type[BaseModel],
    expected_token: str,
    maximum_bytes: int,
    label: str,
    capture_original_key: str | None = None,
) -> BaseModel:
    _require_data_plane_token(
        request.headers.get("X-Serverware-Data-Plane-Token"),
        expected_token,
    )
    content_length = request.headers.get("content-length")
    if content_length is not None:
        try:
            if int(content_length) > maximum_bytes:
                raise HTTPException(
                    status_code=413,
                    detail=f"{label} exceeds {maximum_bytes // 1024} KiB",
                )
        except ValueError as exc:
            raise HTTPException(
                status_code=400, detail="invalid Content-Length"
            ) from exc
    body = bytearray()
    async for chunk in request.stream():
        body.extend(chunk)
        if len(body) > maximum_bytes:
            body.clear()
            raise HTTPException(
                status_code=413,
                detail=f"{label} exceeds {maximum_bytes // 1024} KiB",
            )

    def reject_duplicate_keys(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        value: dict[str, Any] = {}
        for key, item in pairs:
            if key in value:
                raise ValueError(f"duplicate {label} field")
            value[key] = item
        return value

    def reject_non_finite_number(_value: str) -> None:
        raise ValueError("non-finite JSON number")

    try:
        parsed = json.loads(
            body,
            object_pairs_hook=reject_duplicate_keys,
            parse_constant=reject_non_finite_number,
        )
        validated = model_type.model_validate(parsed)
        if capture_original_key is not None:
            if capture_original_key in request.scope:
                raise ValueError("request original was already captured")
            # Keep the parsed original, not a model projection: a holder's
            # signature binds the complete recipient request and its evidence.
            request.scope[capture_original_key] = (validated, parsed)
        return validated
    except ValidationError as exc:
        detail = [
            {key: error[key] for key in ("type", "loc", "msg") if key in error}
            for error in exc.errors(include_url=False, include_input=False)
        ]
        raise HTTPException(status_code=422, detail=detail) from exc
    except (ValueError, json.JSONDecodeError) as exc:
        raise HTTPException(
            status_code=422,
            detail=[
                {
                    "type": "json_invalid",
                    "loc": ["body"],
                    "msg": f"{label} must be exact JSON",
                }
            ],
        ) from exc


