def _approval_is_expired(approval: dict[str, Any]) -> bool:
    return datetime.fromisoformat(approval["expires_at"]) <= datetime.now(timezone.utc)


def _approval_body_hash(canonical: dict[str, Any] | None) -> str | None:
    if not isinstance(canonical, dict):
        return None
    request = (
        canonical.get("request") if isinstance(canonical.get("request"), dict) else {}
    )
    for key in ("body_sha256", "bodySha256", "body_hash", "bodyHash"):
        value = request.get(key) or canonical.get(key)
        if value:
            return str(value)
    return None


SENSITIVE_REVIEW_KEY_PARTS = ("authorization", "password", "secret", "token")


def _redact_review_value(value: Any) -> Any:
    if isinstance(value, dict):
        redacted: dict[str, Any] = {}
        for key, item in value.items():
            if any(part in str(key).lower() for part in SENSITIVE_REVIEW_KEY_PARTS):
                redacted[str(key)] = "[redacted]"
            else:
                redacted[str(key)] = _redact_review_value(item)
        return redacted
    if isinstance(value, list):
        return [_redact_review_value(item) for item in value]
    return value


def _approval_source_identity(canonical: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(canonical, dict):
        return {}
    result: dict[str, Any] = {}
    for key in (
        "client_ip",
        "clientIp",
        "client_cert_sha256",
        "clientCertSha256",
        "spiffe_id",
        "spiffeId",
    ):
        if canonical.get(key):
            result[key] = canonical[key]
    principal = canonical.get("principal") or canonical.get("principal_id")
    if principal:
        result["principal"] = principal
    if canonical.get("proxy_authorization_hash") or canonical.get(
        "proxyAuthorizationHash"
    ):
        result["proxy_authorization"] = "hash-bound"
    return result


def _approval_operation_fields(canonical: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(canonical, dict):
        return {}
    operation = canonical.get("operation")
    if isinstance(operation, dict):
        return _redact_review_value(operation)
    selected: dict[str, Any] = {}
    for key in (
        "operation",
        "operation_type",
        "operationType",
        "package_name",
        "packageName",
        "package_version",
        "packageVersion",
        "tarball_integrity",
        "tarballIntegrity",
        "gmail_user",
        "gmailUser",
    ):
        if canonical.get(key) is not None:
            selected[key] = canonical[key]
    return _redact_review_value(selected)


def _approval_retry_semantics(
    approval: dict[str, Any], jit: dict[str, Any]
) -> dict[str, Any]:
    return {
        "agent_action": "retry-identical-request-through-proxy",
        "server_side_grant": True,
        "agent_receives_secret_or_token": False,
        "request_digest": approval.get("request_digest"),
        "operation_digest": approval.get("operation_digest"),
        "consume_on": jit.get("consumeOn") or "forwardStart",
        "grant_ttl_seconds": approval.get("grant_ttl_seconds") or jit.get("ttlSeconds"),
        "grant_max_uses": approval.get("grant_max_uses") or jit.get("maxUses") or 1,
        "retry_after_seconds": 3,
    }


def _approval_risk_flags(approval: dict[str, Any], jit: dict[str, Any]) -> list[str]:
    flags: list[str] = []
    if _approval_is_expired(approval):
        flags.append("approval_expired")
    if approval.get("credential_version") is not None:
        flags.append("credential_version_bound")
    if approval.get("policy_hash"):
        snapshot = get_policy_snapshot()
        flags.append(
            "policy_hash_current"
            if snapshot and snapshot.hash == approval.get("policy_hash")
            else "policy_hash_not_current"
        )
    authn = _approval_authn_policy(jit)
    if _webauthn_required(authn):
        flags.append("webauthn_required")
    if authn.get("requireHardwareAttestation"):
        flags.append("hardware_attestation_required")
    if int(approval.get("grant_max_uses") or jit.get("maxUses") or 1) == 1:
        flags.append("one_use_grant")
    return flags


def _approval_history_item(item: dict[str, Any]) -> dict[str, Any]:
    authn = (
        item.get("approval_authn")
        if isinstance(item.get("approval_authn"), dict)
        else {}
    )
    return {
        "id": item["id"],
        "status": item.get("status"),
        "requested_at": item.get("requested_at"),
        "expires_at": item.get("expires_at"),
        "approved_until": item.get("approved_until"),
        "decision_note": item.get("decision_note"),
        "approved_by": item.get("approved_by"),
        "authn": {
            "method": authn.get("method"),
            "authenticator_class": authn.get("authenticator_class"),
            "user_verified": authn.get("user_verified"),
        },
        "request_digest": item.get("request_digest"),
        "operation_digest": item.get("operation_digest"),
    }


def _approval_review_document(approval: dict[str, Any]) -> dict[str, Any]:
    canonical = (
        approval.get("canonical_request")
        if isinstance(approval.get("canonical_request"), dict)
        else {}
    )
    redacted_display = (
        approval.get("redacted_display")
        if isinstance(approval.get("redacted_display"), dict)
        else {}
    )
    try:
        jit = _approval_jit_policy(approval)
    except HTTPException:
        jit = {}
    similar = db.list_similar_approvals(approval, limit=5)
    return {
        "id": approval["id"],
        "status": approval.get("status"),
        "decision_note": approval.get("decision_note"),
        "principal_id": approval.get("principal_id"),
        "source_identity": _approval_source_identity(canonical),
        "route_id": approval.get("route_id"),
        "credential_ref": approval.get("credential_id"),
        "credential_version": approval.get("credential_version"),
        "policy_hash": approval.get("policy_hash"),
        "method": approval.get("method"),
        "url": approval.get("url"),
        "normalized_operation_fields": _approval_operation_fields(canonical),
        "body_hash": _approval_body_hash(canonical),
        "redacted_payload_summary": _redact_review_value(redacted_display),
        "risk_flags": _approval_risk_flags(approval, jit),
        "requested_at": approval.get("requested_at"),
        "expires_at": approval.get("expires_at"),
        "previous_similar_approvals": [
            _approval_history_item(item) for item in similar
        ],
        "retry_semantics": _approval_retry_semantics(approval, jit),
    }


@app.post("/attestation/challenge")
def attestation_challenge(request: Request) -> Response:
    try:
        production_state = production_attestation_state()
        tls_scope = trusted_tls_scope_from_asgi(
            request.scope, production_state=production_state
        )
        document = issue_attestation_challenge(tls_scope)
    except AttestationContractError as exc:
        raise HTTPException(
            status_code=503,
            detail="attestation challenge service is unavailable",
        ) from exc
    return Response(
        content=attestation_canonical_json(document).encode("ascii"),
        media_type="application/json",
        headers={"Cache-Control": "no-store", "Pragma": "no-cache"},
    )


def _produce_public_evidence_from_scope(
    *,
    raw_request_body: bytes,
    scope: Mapping[str, Any],
) -> Any:
    descriptor = _load_public_evidence_producer_descriptor()
    tls_scope = trusted_public_tls_scope_from_asgi(
        scope,
        descriptor=descriptor,
    )
    return production_public_evidence_response(
        raw_request_body=raw_request_body,
        tls_scope=tls_scope,
        descriptor=descriptor,
    )


def _finish_public_evidence_worker(
    worker: asyncio.Task[Any],
    *,
    route_slots: asyncio.BoundedSemaphore,
) -> None:
    route_slots.release()
    if not worker.cancelled():
        worker.exception()


@app.post("/attestation/public-evidence")
async def attestation_public_evidence(request: Request) -> Response:
    if request.headers.get("content-type") != "application/json":
        raise HTTPException(
            status_code=415,
            detail="public attestation evidence requires application/json",
        )
    raw_query = request.scope.get("query_string", b"")
    if type(raw_query) is not bytes or raw_query:
        raise HTTPException(
            status_code=400,
            detail="public attestation evidence does not accept a query string",
        )
    raw_content_length = request.headers.get("content-length")
    if raw_content_length is not None:
        try:
            content_length = int(raw_content_length)
        except ValueError as exc:
            raise HTTPException(
                status_code=400,
                detail="invalid Content-Length",
            ) from exc
        if (
            content_length < 0
            or content_length > _PUBLIC_EVIDENCE_REQUEST_MAX_BYTES
        ):
            raise HTTPException(
                status_code=413,
                detail="public attestation request exceeds 4 KiB",
            )
    try:
        extensions = request.scope.get("extensions")
        if (
            not isinstance(extensions, Mapping)
            or TRUSTED_TLS_SCOPE_EXTENSION not in extensions
        ):
            raise AttestationContractError(
                "trusted enclave TLS extension is unavailable"
            )
        bounded_body = bytearray()
        async for chunk in request.stream():
            if (
                len(chunk)
                > _PUBLIC_EVIDENCE_REQUEST_MAX_BYTES - len(bounded_body)
            ):
                raise HTTPException(
                    status_code=413,
                    detail="public attestation request exceeds 4 KiB",
                )
            bounded_body.extend(chunk)
        raw_request_body = bytes(bounded_body)
        if not raw_request_body:
            raise AttestationContractError(
                "public evidence request body is empty"
            )
        route_slots = _PUBLIC_EVIDENCE_ROUTE_SLOTS
        try:
            await asyncio.wait_for(
                route_slots.acquire(),
                timeout=0.05,
            )
        except TimeoutError as exc:
            raise AttestationContractError(
                "public evidence producer is at its concurrency limit"
            ) from exc
        try:
            worker = asyncio.create_task(
                asyncio.to_thread(
                    _produce_public_evidence_from_scope,
                    raw_request_body=raw_request_body,
                    scope=request.scope,
                )
            )
        except Exception:
            route_slots.release()
            raise
        worker.add_done_callback(
            lambda completed, slots=route_slots: _finish_public_evidence_worker(
                completed,
                route_slots=slots,
            )
        )
        result = await asyncio.shield(worker)
        response = Response(
            content=result.body,
            status_code=result.status_code,
            media_type=None,
        )
        response.raw_headers = list(result.raw_headers)
    except AttestationContractError as exc:
        message = str(exc)
        unavailable = (
            "unavailable" in message
            or "configured" in message
            or "ordinary host TLS" in message
            or "enclave TLS extension" in message
            or "producer" in message
            or "single-worker" in message
        )
        raise HTTPException(
            status_code=503 if unavailable else 403,
            detail=(
                "public attestation evidence is unavailable from this TLS stack"
                if unavailable
                else "public attestation evidence request was rejected"
            ),
        ) from exc
    return response


@app.get("/attestation")
def attestation(
    request: Request,
    nonce: str | None = None,
    challenge_id: str | None = Query(default=None, alias="challengeId"),
    challenge: str | None = None,
) -> Response | dict[str, Any]:
    production = RELEASE_CHANNEL.strip().lower() not in {
        "dev",
        "development",
        "local",
        "test",
    }
    if not production:
        return attestation_document(nonce)
    if nonce is not None or challenge_id is None or challenge is None:
        raise HTTPException(
            status_code=400,
            detail="production attestation requires one issued challenge",
        )
    raw_query_value = request.scope.get("query_string", b"")
    if (
        type(raw_query_value) is not bytes
        or len(raw_query_value) > 4096
    ):
        raise HTTPException(
            status_code=400,
            detail="attestation request query is invalid",
        )
    try:
        raw_query = raw_query_value.decode("ascii", errors="strict")
        production_state = production_attestation_state()
        tls_scope = trusted_tls_scope_from_asgi(
            request.scope, production_state=production_state
        )
        reservation = reserve_attestation_challenge(
            challenge_id,
            challenge,
            tls_scope,
        )
        try:
            result = production_attestation_response(
                challenge=reservation.challenge,
                tls_scope=tls_scope,
                method=request.method,
                path=request.url.path,
                raw_query=raw_query,
                production_state=production_state,
            )
            response = Response(
                content=result.body,
                status_code=result.status_code,
                media_type=None,
            )
            response.raw_headers = list(result.raw_headers)
            finalize_attestation_challenge(reservation)
        except Exception:
            release_attestation_challenge(reservation)
            raise
    except UnicodeDecodeError as exc:
        raise HTTPException(
            status_code=400,
            detail="attestation request query is invalid",
        ) from exc
    except AttestationContractError as exc:
        message = str(exc)
        unavailable = (
            "unavailable" in message
            or "configured" in message
            or "ordinary host TLS" in message
            or "enclave TLS extension" in message
        )
        raise HTTPException(
            status_code=503 if unavailable else 403,
            detail=(
                "production attestation is unavailable from this TLS stack"
                if unavailable
                else "production attestation request was rejected"
            ),
        ) from exc
    return response


