@app.post("/api/key-release/verify")
def key_release_verify(
    payload: KeyReleaseVerify,
    _: AdminIdentity = Depends(require_role("admin")),
) -> dict[str, Any]:
    try:
        return release_material(
            payload.material,
            expected_policy_hash=payload.expected_policy_hash,
            expected_policy_sequence=payload.expected_policy_sequence,
            expected_policy_high_water_digest=payload.expected_policy_high_water_digest,
            expected_ca_spki=payload.expected_ca_spki,
            expected_rollback_epoch=payload.expected_rollback_epoch,
            expected_release_channel=payload.expected_release_channel,
            expected_provenance_digest=payload.expected_provenance_digest,
            expected_data_plane_binary_digest=payload.expected_data_plane_binary_digest,
        )
    except KeyReleaseError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc


@app.get("/api/bootstrap")
def bootstrap(identity: AdminIdentity = Depends(require_admin)) -> dict[str, Any]:
    snapshot = get_policy_snapshot()
    metadata = snapshot.raw.get("metadata") if snapshot else {}
    can_view_credentials = identity.has_any_role({"policy_author", "credential_owner"})
    can_view_routes = identity.has_any_role(
        {"policy_author", "policy_publisher", "auditor"}
    )
    can_view_approvals = identity.has_any_role({"approver", "auditor"})
    can_view_logs = identity.has_any_role({"auditor"})
    credentials = db.list_credentials() if can_view_credentials else []
    pending_oauth_credentials, oauth_issuance_uncertainties = [], []
    if can_view_credentials:
        from serverware import oauth_read_projections
        actor_filter = None if identity.has_any_role({"admin"}) else identity.user_id
        try:
            oauth_owner = oauth_read_projections.source_owner()
            if oauth_owner is not None:
                pending_oauth_credentials = oauth_read_projections.pending(oauth_owner, requester_id=actor_filter)
                oauth_issuance_uncertainties = oauth_read_projections.uncertainties(oauth_owner, actor_id=actor_filter)
        except Exception:
            raise HTTPException(status_code=503, detail="OAuth observations unavailable; no expiry, cleanup or retry is authorized") from None
        if oauth_owner is None:
            pending_oauth_credentials = db.list_pending_oauth_credentials(requester_id=actor_filter)
            oauth_issuance_uncertainties = db.list_oauth_issuance_uncertainties(actor_id=actor_filter)
    routes = db.list_routes() if can_view_routes else []
    approvals = db.list_approvals(limit=100) if can_view_approvals else []
    logs = db.list_logs(limit=150) if can_view_logs else []
    policy_principals = (
        policy_principal_summaries(snapshot)
        if snapshot is not None and can_view_routes
        else []
    )
    webauthn_credential_history = db.list_webauthn_credentials(
        identity.user_id, include_revoked=True
    )
    webauthn_credential_count = sum(
        1 for item in webauthn_credential_history if item.get("revoked_at") is None
    )
    result = {
        "credentials": credentials,
        "pendingOAuthCredentials": pending_oauth_credentials,
        "oauthIssuanceUncertainties": oauth_issuance_uncertainties,
        "routes": routes,
        "approvals": approvals,
        "logs": logs,
        "ca_ready": (MITMPROXY_CONF_DIR / "mitmproxy-ca-cert.pem").exists(),
        "policy_ready": snapshot is not None,
        "policy_hash": snapshot.hash if snapshot else None,
        "policy_signature": metadata.get("signature")
        if isinstance(metadata, dict)
        else None,
        "policy_signing_key_id": metadata.get("signingKeyId")
        if isinstance(metadata, dict)
        else None,
        "policy_path": str(POLICY_BUNDLE_PATH),
        "publicUrl": canonical_control_plane_url(PUBLIC_URL),
        "policyPrincipals": policy_principals,
        "oauthProviders": provider_status_with_custody() if can_view_credentials else [],
        "currentUserId": identity.user_id,
        "currentUserRoles": sorted(identity.roles),
        "webauthnCredentialCount": webauthn_credential_count,
        "webauthnCredentialHistoryCount": len(webauthn_credential_history),
        "webauthnCredentials": [
            _redacted_webauthn_credential(item)
            for item in webauthn_credential_history
        ],
        "webauthnBootstrapRequired": (
            len(webauthn_credential_history) == 0
            and RELEASE_CHANNEL.strip().lower()
            not in {"dev", "development", "local", "test"}
        ),
        **admin_status(),
    }
    db.record_audit_event(
        "control_plane.bootstrap",
        {
            "policy_hash": snapshot.hash if snapshot else None,
            "counts": {
                "credentials": len(credentials),
                "pending_oauth_credentials": len(pending_oauth_credentials),
                "oauth_issuance_uncertainties": len(oauth_issuance_uncertainties),
                "routes": len(routes),
                "approvals": len(approvals),
                "logs": len(logs),
                "webauthn_credentials": webauthn_credential_count,
            },
            "auth_method": identity.auth_method,
        },
        actor_id=identity.user_id,
    )
    return result


@app.get("/api/csrf")
def csrf_token(
    response: Response,
    request: Request,
    x_serverware_admin_token: str | None = Header(
        default=None, alias="X-Serverware-Admin-Token"
    ),
) -> dict[str, Any]:
    try:
        require_admin(request, x_serverware_admin_token)
    except HTTPException as exc:
        if exc.status_code != 401:
            raise
        _oidc_session_for_request(request)
    token = issue_csrf_cookie(response, request)
    return {
        "ok": True,
        "token": token,
        "cookie": CSRF_COOKIE_NAME,
        "header": CSRF_HEADER_NAME,
    }


@app.post("/api/authority/webauthn/challenges")
def authority_webauthn_challenge(
    payload: AuthorityWebAuthnChallengeRequest,
    identity: AdminIdentity = Depends(
        require_role(
            "admin",
            "policy_author",
            "policy_publisher",
            "credential_owner",
            "approver",
            "attestation_reviewer",
        )
    ),
) -> dict[str, Any]:
    try:
        operation = authority_contract.operation_spec(payload.operation)
    except ValueError as exc:
        raise HTTPException(
            status_code=400,
            detail="authority operation is not allowlisted",
        ) from exc
    if not bool(operation["assertionRequired"]):
        raise HTTPException(
            status_code=400,
            detail="authority operation does not accept WebAuthn evidence",
        )
    required_roles = _authority_operator_roles(payload.operation)
    if required_roles is None or not identity.has_any_role(
        set(required_roles)
    ):
        raise HTTPException(
            status_code=403,
            detail="current identity cannot authorize this operation",
        )
    credential = db.get_webauthn_credential_by_record_id(
        payload.credential_record_id
    )
    if (
        credential is None
        or credential.get("user_id") != identity.user_id
        or credential.get("revoked_at") is not None
    ):
        raise HTTPException(
            status_code=404,
            detail="active WebAuthn credential was not found",
        )
    try:
        challenge = db.issue_policy_authority_webauthn_challenge(
            operation=payload.operation,
            input_value=payload.arguments,
            user_id=identity.user_id,
            credential_id=str(credential["credential_id"]),
        )
    except (
        db.MetadataStoreError,
        db.PolicyCandidateAuthorityError,
        RuntimeError,
    ) as exc:
        raise HTTPException(
            status_code=503,
            detail="authority WebAuthn challenge is unavailable",
        ) from exc
    challenge_payload = (
        challenge.get("payload")
        if isinstance(challenge, Mapping)
        else None
    )
    if (
        not isinstance(challenge, Mapping)
        or set(challenge)
        != {
            "id",
            "challenge",
            "challenge_type",
            "user_id",
            "scope_key",
            "approval_request_id",
            "expires_at",
            "used_at",
            "created_at",
            "payload",
        }
        or not isinstance(challenge_payload, Mapping)
        or set(challenge_payload)
        != {
            "schema",
            "operationId",
            "rpId",
            "origin",
            "issuedAtEpochNs",
            "expiresAtEpochNs",
            "credentialId",
        }
        or challenge.get("challenge_type") != "policy_authority"
        or challenge.get("user_id") != identity.user_id
        or challenge.get("used_at") is not None
        or challenge.get("approval_request_id") is not None
        or challenge_payload.get("schema")
        != "serverware.policyAuthorityWebAuthnChallenge/v1"
        or challenge.get("scope_key")
        != challenge_payload.get("operationId")
        or challenge_payload.get("credentialId")
        != credential["credential_id"]
        or not isinstance(challenge_payload.get("rpId"), str)
        or not isinstance(challenge_payload.get("origin"), str)
        or not isinstance(
            challenge_payload.get("issuedAtEpochNs"), int
        )
        or not isinstance(
            challenge_payload.get("expiresAtEpochNs"), int
        )
        or challenge_payload["expiresAtEpochNs"]
        <= challenge_payload["issuedAtEpochNs"]
        or not isinstance(challenge.get("challenge"), str)
    ):
        raise HTTPException(
            status_code=503,
            detail="authority WebAuthn challenge response is not closed",
        )
    return {
        "apiVersion": "serverware.policyAuthorityBrowserChallenge/v1",
        "operation": payload.operation,
        "challengeId": challenge["id"],
        "credentialRecordId": credential["id"],
        "expiresAt": challenge["expires_at"],
        "publicKey": {
            "challenge": challenge["challenge"],
            "rpId": challenge_payload["rpId"],
            "timeout": 300_000,
            "userVerification": "required",
            "allowCredentials": [
                {
                    "type": "public-key",
                    "id": credential["credential_id"],
                }
            ],
        },
    }


