def _control_plane_custody_response(action: str, *args: Any) -> JSONResponse:
    from serverware import control_plane_custody_recovery as recovery

    headers = {"Cache-Control": "no-store", "Pragma": "no-cache",
        "X-Content-Type-Options": "nosniff"}
    try:
        function = {"inventory": recovery.inventory, "inspect": recovery.inspect_record,
            "reconcile": recovery.reconcile}[action]
        return JSONResponse(content=function(*args), headers=headers)
    except recovery.CustodyRecordNotFound:
        return JSONResponse(status_code=404, headers=headers,
            content={"detail": {"error": "local_custody_record_not_found", "remoteState": "unknown"}})
    except recovery.CustodyRecordNotAttempted:
        return JSONResponse(status_code=409, headers=headers,
            content={"detail": {"error": "custody_record_not_attempted", "remoteState": "unknown"}})
    except recovery.CustodyRecoveryUnavailable:
        return JSONResponse(status_code=503, headers=headers,
            content={"detail": {"error": "custody_recovery_unavailable", "remoteState": "unknown"}})


@app.get("/api/authority/control-plane/custody")
def control_plane_custody_inventory(
    request: Request,
    _: AdminIdentity = Depends(require_role("admin")),
) -> JSONResponse:
    if request.scope.get("query_string", b""):
        raise HTTPException(status_code=400, detail="custody inventory does not accept a query string")
    return _control_plane_custody_response("inventory")


@app.get("/api/authority/control-plane/custody/{local_digest}")
def control_plane_custody_record(
    local_digest: str,
    request: Request,
    _: AdminIdentity = Depends(require_role("admin")),
) -> JSONResponse:
    if (request.scope.get("query_string", b"")
            or re.fullmatch(r"sha256:[0-9a-f]{64}", local_digest) is None):
        raise HTTPException(status_code=400, detail="custody record requires one canonical local digest")
    return _control_plane_custody_response("inspect", local_digest)


@app.post("/api/authority/control-plane/custody/reconcile")
def control_plane_custody_reconcile(
    request: Request,
    payload: CustodyReconcileRequest,
    _: AdminIdentity = Depends(require_role("admin")),
) -> JSONResponse:
    # Readback is separate from authority execution. No caller-supplied plan body,
    # source, key, configuration, deadline or original record enters this call.
    if request.scope.get("query_string", b""):
        raise HTTPException(status_code=400, detail="custody reconciliation does not accept a query string")
    return _control_plane_custody_response("reconcile", payload.local_digest)


@app.post("/api/authority/control-plane/execute")
def execute_control_plane_authority_operation(
    request: Request,
    payload: ControlledAuthorityExecuteRequest,
    identity: AdminIdentity = Depends(
        require_role(
            "admin",
            "policy_publisher",
            "auditor",
            "credential_owner",
            "approver",
            "attestation_reviewer",
        )
    ),
) -> dict[str, Any]:
    try:
        operation = authority_contract.operation_spec(payload.operation)
    except ValueError as exc:
        raise HTTPException(
            status_code=400,
            detail="control-plane authority operation is not allowlisted",
        ) from exc
    allowed_roles = _authority_operator_roles(payload.operation)
    if allowed_roles is None:
        raise HTTPException(
            status_code=400,
            detail="control-plane authority operation is not allowlisted",
        )
    if not identity.has_any_role(set(allowed_roles)):
        raise HTTPException(
            status_code=403,
            detail="current identity cannot dispatch this authority operation",
        )
    content_length = request.headers.get("content-length")
    try:
        content_length_value = int(content_length or "")
    except ValueError as exc:
        raise HTTPException(
            status_code=411,
            detail="authority execution requires a bounded content length",
        ) from exc
    if (
        request.scope.get("query_string", b"")
        or request.headers.get("content-type") != "application/json"
        or not 2 <= content_length_value <= 16 * 1024 * 1024
    ):
        raise HTTPException(
            status_code=415,
            detail="authority execution requires exact bounded JSON framing",
        )
    assertion_fields = (
        "authn",
        "authn_evidence",
        "webauthn_authorization",
    )
    has_assertion = any(
        isinstance(payload.arguments.get(field), Mapping)
        for field in assertion_fields
    )
    base_arguments = {
        key: value
        for key, value in payload.arguments.items()
        if key not in assertion_fields
    }
    base_payload_digest = "sha256:" + hashlib.sha256(
        _policy_authority_canonical_bytes(
            {
                "operation": payload.operation,
                "arguments": base_arguments,
            }
        )
    ).hexdigest()
    try:
        recovered = db.get_policy_control_plane_exact_result(
            request_id=payload.request_id,
            operation=payload.operation,
            base_payload_digest=base_payload_digest,
            actor_id=identity.user_id,
        )
    except db.PolicyCandidateAuthorityConflictError as exc:
        raise HTTPException(
            status_code=409,
            detail="authority request ID was already used differently",
        ) from exc
    except (
        db.MetadataStoreError,
        db.PolicyCandidateAuthorityError,
    ) as exc:
        raise HTTPException(
            status_code=503,
            detail="authority exact-result recovery is unavailable",
        ) from exc
    if recovered is not None:
        return _policy_authority_plain(recovered)
    if bool(operation["assertionRequired"]) and not has_assertion:
        raise HTTPException(
            status_code=428,
            detail={
                "error": "authority_webauthn_required",
                "operation": payload.operation,
                "challengeEndpoint":
                    "/api/authority/webauthn/challenges",
                "continuationEndpoint":
                    "/api/authority/control-plane/execute",
                "requestId": payload.request_id,
            },
        )
    payload_digest = "sha256:" + hashlib.sha256(
        _policy_authority_canonical_bytes(
            {
                "operation": payload.operation,
                "arguments": payload.arguments,
            }
        )
    ).hexdigest()
    try:
        db.claim_policy_control_plane_request(
            request_id=payload.request_id,
            operation=payload.operation,
            payload_digest=payload_digest,
            actor_type="admin",
            actor_id=identity.user_id,
            allow_exact_retry=True,
        )
        result = db.dispatch_policy_authority_operation(
            payload.operation,
            {
                "schema":
                    "serverware.policyAuthorityControlledWriterInput/v1",
                "handler": operation["handler"],
                "operationManifestDigest":
                    authority_contract.OPERATION_MANIFEST_DIGEST,
                "arguments": payload.arguments,
            },
        )
        db.stage_policy_control_plane_exact_result(
            request_id=payload.request_id,
            operation=payload.operation,
            base_payload_digest=base_payload_digest,
            actor_id=identity.user_id,
            response=result,
        )
        return result
    except db.PolicyCandidateAuthorityConflictError as exc:
        raise HTTPException(
            status_code=409,
            detail="authority request ID was already used",
        ) from exc
    except (
        db.MetadataStoreError,
        db.PolicyCandidateAuthorityError,
        RuntimeError,
    ) as exc:
        raise HTTPException(
            status_code=409,
            detail="control-plane authority operation was denied",
        ) from exc


@app.post("/api/control-plane/mutations/webauthn/options")
def control_plane_mutation_webauthn_options(
    payload: PublicRevocationApprovalWebAuthnOptions | OAuthActivationWebAuthnOptions | PublicationApprovalWebAuthnOptions | ControlPlaneMutationWebAuthnOptions,
    request: Request,
    identity: AdminIdentity = Depends(
        require_role(
            "admin",
            "policy_author",
            "policy_publisher",
            "credential_owner",
            "approver",
            "attestation_reviewer",
        )
    ),
) -> dict[str, Any]:
    if payload.action == "webauthn.credential.revoke":
        from serverware import control_plane_public_revocation as public_revocation
        if type(payload) is PublicRevocationApprovalWebAuthnOptions:
            from serverware import control_plane_public_revocation_approval
            try:
                return control_plane_public_revocation_approval.options_on_request(
                    request, public_revocation.body_original(request))
            except HTTPException:
                raise
            except Exception:
                raise HTTPException(status_code=409, detail="public revocation approval options unavailable; no automatic retry") from None
        if public_revocation.selected() or payload.api_version is not None:
            raise HTTPException(status_code=409, detail="use the explicit public revocation approval options profile")
    if payload.action == "credential.oauth.activate":
        from serverware import control_plane_oauth_activation as oauth_activation
        if type(payload) is OAuthActivationWebAuthnOptions:
            try:
                return oauth_activation.options_on_request(request, payload)
            except HTTPException:
                raise
            except Exception:
                raise HTTPException(status_code=409, detail="OAuth activation options unavailable; no automatic retry") from None
        if payload.api_version is not None or oauth_activation.selected():
            raise HTTPException(status_code=409, detail="use the explicit OAuth activation approval options profile")
    if payload.action in {"credential.oauth.setup-create", "credential.oauth.setup-activate"}:
        raise HTTPException(status_code=409, detail="use the explicit controlled Setup purpose endpoint")
    if payload.action in {"policy.file.materialize", "policy.file.genesis.materialize", "policy.file.resolve"}:
        raise HTTPException(status_code=409, detail="use the explicit policy-file approval options endpoint")
    if type(payload) is PublicationApprovalWebAuthnOptions:
        from serverware import control_plane_publication_authorization as publication_authority
        try:
            return publication_authority.options_on_request(request, payload)
        except HTTPException:
            raise
        except Exception:
            raise HTTPException(status_code=409, detail="publication authority options are unavailable; no automatic retry") from None
    if payload.action == "control_plane.token.publication.resolve":
        from serverware import control_plane_custody_startup
        if payload.api_version is not None or control_plane_custody_startup.require_started() is not None:
            raise HTTPException(status_code=409, detail="use the explicit publication approval options profile")
    _control_plane_approval_roles(payload.action)
    if payload.action == "workload.identity.issue":
        from serverware import control_plane_workload_identity_routes as workload_routes

        # Requesters derive these bindings only from genuine original grants
        # at the dedicated options route; this generic route is approver-only.
        if not payload.approval_id:
            raise HTTPException(status_code=403, detail="use workload issuance original options")
        identity = workload_routes._cookie_identity(request, approver=True)
    approval_context = None
    if payload.approval_id:
        approval_context = db.get_control_plane_approval(payload.approval_id)
        if not approval_context:
            raise HTTPException(status_code=404, detail="control-plane approval not found")
        if approval_context["status"] != "pending":
            raise HTTPException(status_code=409, detail="control-plane approval is not pending")
        if approval_context["requester_id"] == identity.user_id:
            raise HTTPException(status_code=403, detail="requester cannot approve own mutation")
        _assert_control_plane_approval_role(identity, approval_context["action"])
        expected = (
            approval_context["action"],
            approval_context["resource_id"],
            approval_context["payload_digest"],
        )
        if expected != (payload.action, payload.resource_id, payload.payload_digest):
            raise HTTPException(status_code=409, detail="approval challenge binding mismatch")
    return control_plane_mutation_options(
        user_id=identity.user_id,
        action=payload.action,
        resource_id=payload.resource_id,
        payload_digest=payload.payload_digest,
        authn_policy=_control_plane_mutation_authn_policy(),
        approval_context=approval_context,
    )


@app.get("/api/rbac/role-bindings")
def rbac_role_bindings(
    _: AdminIdentity = Depends(require_role("admin", "auditor")),
) -> dict[str, Any]:
    return _read_rbac_bindings()


@app.put("/api/rbac/role-bindings/{subject_id:path}")
def rbac_role_binding_update(
    subject_id: str,
    payload: RoleBindingUpdate,
    identity: AdminIdentity = Depends(require_role("admin")),
) -> dict[str, Any]:
    del subject_id, payload, identity
    raise HTTPException(
        status_code=409,
        detail={
            "error": "legacy_rbac_mutation_disabled",
            "authorityEndpoint": "/api/authority/control-plane/execute",
            "challengeEndpoint":
                "/api/authority/webauthn/challenges",
        },
    )
    roles = _normalized_rbac_roles(payload.roles)
    payload_digest = _rbac_change_payload_digest(subject_id, payload)
    _preflight_rbac_generation(payload.expected_generation)
    mfa = _require_control_plane_mutation_mfa(
        action="rbac.role.change",
        resource_id=subject_id,
        payload_digest=payload_digest,
        mfa=payload.mfa,
        identity=identity,
    )
    try:
        two_person = _require_control_plane_two_person(
            action="rbac.role.change",
            resource_id=subject_id,
            payload_digest=payload_digest,
            mfa=payload.mfa,
            identity=identity,
            request={
                "subject_id": subject_id,
                "roles": roles,
                "expected_generation": payload.expected_generation,
                "reason": payload.reason,
            },
        )
        result = db.mutate_rbac_role_binding(
            subject_id=subject_id,
            roles=roles,
            status="active",
            expected_generation=payload.expected_generation,
            actor_id=identity.user_id,
            reason=payload.reason,
            event_type="rbac.role_changed",
            event={
                "reason": payload.reason,
                "control_plane_mfa": mfa,
                "control_plane_approval": two_person,
                "payload_digest": payload_digest,
            },
            authn=mfa,
            challenge_id=(
                mfa.get("challenge_id")
                if isinstance(mfa, dict)
                else None
            ),
        )
    except db.RBACGenerationConflictError as exc:
        raise _rbac_generation_conflict(
            exc.expected_generation, exc.current_generation
        ) from exc
    except db.PolicyCandidateAuthorityError as exc:
        raise HTTPException(
            status_code=409,
            detail=(
                "RBAC mutation requires a closed authority transaction "
                "proposal at /api/authority/control-plane/execute"
            ),
        ) from exc
    except (db.RBACBindingStoreError, db.AuditStoreError) as exc:
        raise HTTPException(status_code=503, detail="RBAC mutation failed") from exc
    try:
        projected = db.project_rbac_authority_state()
        result["projection"] = {
            "status": "current",
            "generation": projected["generation"],
            "state_digest": projected["state_digest"],
        }
    except db.RBACBindingStoreError:
        result["projection"] = {
            "status": "pending",
            "generation": result["generation"],
        }
    return {"ok": True, **result}


