@app.get("/api/control-plane/approvals")
def control_plane_approvals(
    status: str | None = None,
    limit: int = Query(100, ge=1, le=500),
    identity: AdminIdentity = Depends(
        require_role(
            "auditor",
            "policy_publisher",
            "credential_owner",
            "policy_author",
            "attestation_reviewer",
            "approver",
        )
    ),
) -> list[dict[str, Any]]:
    results: list[dict[str, Any]] = []
    for item in db.list_control_plane_approvals(status=status, limit=limit):
        from serverware import control_plane_policy_genesis_maintenance as genesis_maintenance
        if not genesis_maintenance.visible_approval(item):
            continue
        required_roles = _control_plane_approval_roles(str(item["action"]))
        pending = item.get("status") == "pending"
        has_role = identity.has_any_role(required_roles)
        is_requester = item.get("requester_id") == identity.user_id
        can_approve = pending and has_role and not is_requester
        can_deny = pending and has_role
        approve_block_reason = None
        deny_block_reason = None
        if not pending:
            approve_block_reason = f"Approval is already {item.get('status')}."
            deny_block_reason = approve_block_reason
        elif not has_role:
            role_text = " or ".join(sorted(required_roles))
            approve_block_reason = f"Requires role: {role_text}."
            deny_block_reason = approve_block_reason
        elif is_requester:
            approve_block_reason = (
                "A different authorized operator must approve this request."
            )
        results.append(
            {
                **item,
                "required_approver_roles": sorted(required_roles),
                "can_approve": can_approve,
                "can_deny": can_deny,
                "approve_block_reason": approve_block_reason,
                "deny_block_reason": deny_block_reason,
            }
        )
    return results


@app.post("/api/control-plane/approvals/{approval_id}/approve")
def control_plane_approval_approve(
    approval_id: str,
    request: Request,
    payload: PublicRevocationApprovalSubmit | ControlPlaneApprovalDecision | None = Body(default=None),
    identity: AdminIdentity = Depends(require_admin),
) -> dict[str, Any]:
    decision = payload if isinstance(payload, ControlPlaneApprovalDecision) else None
    approval = db.get_control_plane_approval(approval_id)
    if not approval:
        raise HTTPException(status_code=404, detail="control-plane approval not found")
    if approval["status"] != "pending":
        raise HTTPException(
            status_code=409,
            detail=f"control-plane approval is already {approval['status']}",
        )
    if approval["action"] == "webauthn.credential.revoke":
        from serverware import control_plane_public_revocation as public_revocation
        if type(payload) is PublicRevocationApprovalSubmit:
            from serverware import control_plane_public_revocation_approval
            try:
                return control_plane_public_revocation_approval.submit_on_request(request,
                    approval["resource_id"], public_revocation.body_original(request), approval_id=approval_id)
            except HTTPException:
                raise
            except Exception:
                raise HTTPException(status_code=409, detail="public revocation approval outcome unresolved; no automatic retry") from None
        if public_revocation.selected():
            raise HTTPException(status_code=409, detail="use the explicit public revocation approval submission")
    if approval["action"] == "credential.oauth.setup-activate":
        from serverware import control_plane_oauth_activation as oauth_activation
        from serverware import authority_oauth_setup as setup_profile
        try:
            return oauth_activation.decide_on_request(request, approval_id, decision, contract=setup_profile)
        except HTTPException:
            raise
        except Exception:
            raise HTTPException(status_code=409, detail="Setup decision uncertain or blocked; no automatic retry") from None
    if approval["action"] == "credential.oauth.activate":
        from serverware import control_plane_oauth_activation as oauth_activation
        if (oauth_activation.selected() or decision is not None and isinstance(decision.mfa, dict)
                and oauth_activation.MFA_FIELD in decision.mfa):
            try:
                return oauth_activation.decide_on_request(request, approval_id, decision)
            except HTTPException:
                raise
            except Exception:
                raise HTTPException(status_code=409, detail="OAuth activation decision uncertain or blocked; no automatic retry") from None
    if approval["action"] in {"policy.file.materialize", "policy.file.genesis.materialize", "policy.file.resolve"}:
        from serverware import control_plane_publication_authorization as publication_authority
        try:
            return publication_authority.decide_on_request(request, approval_id, decision, purpose="policy-file")
        except HTTPException:
            raise
        except Exception:
            raise HTTPException(status_code=409, detail="policy-file approval decision uncertain; no automatic retry") from None
    if approval["action"] == "control_plane.token.publication.resolve":
        from serverware import control_plane_custody_startup
        if (control_plane_custody_startup.require_started() is not None
                or decision is not None and type(decision.mfa) is dict and "publicationProfile" in decision.mfa):
            from serverware import control_plane_publication_authorization as publication_authority
            try:
                return publication_authority.decide_on_request(request, approval_id, decision)
            except HTTPException:
                raise
            except Exception:
                raise HTTPException(status_code=409, detail="publication approval decision uncertain; no automatic retry") from None
    workload_issuance = approval["action"] == "workload.identity.issue"
    mandatory_webauthn = _control_plane_mutation_webauthn_required(approval["action"])
    if workload_issuance:
        from serverware import control_plane_workload_identity_routes as workload_routes

        identity = workload_routes._cookie_identity(request, approver=True)
    if approval["requester_id"] == identity.user_id:
        raise HTTPException(
            status_code=403,
            detail="requester cannot approve their own control-plane mutation",
        )
    _assert_control_plane_approval_role(identity, approval["action"])
    workload_receipt = None
    verified_receipt = None
    if workload_issuance:
        identity, workload_receipt = workload_routes._approve_assertion(
            request, approval, decision.mfa if decision else None)
    elif mandatory_webauthn:
        from serverware import control_plane_approval_verification as approval_verification

        try:
            identity, verified_receipt = approval_verification._verify_on_request(
                request, approval=approval, mfa=decision.mfa if decision else None)
        except approval_verification.ApprovalVerificationError:
            raise HTTPException(status_code=403,
                detail="control-plane approval verification is unavailable") from None
    try:
        # The fresh verifier has consumed its challenge. Only its private,
        # one-use receipt crosses into the transaction; metadata is not a new
        # raw assertion. Optional-MFA authentication remains a separate branch.
        updated = db.approve_control_plane_approval(
            approval_id,
            actor_id=identity.user_id,
            note=decision.note if decision else None,
            authn=None if workload_issuance or mandatory_webauthn else {
                "method": identity.auth_method,
                "user_id": identity.user_id,
            },
            challenge_id=None,
            require_webauthn=workload_issuance or mandatory_webauthn,
            workload_approval=workload_receipt,
            verified_approval=verified_receipt,
            required_approver_roles=_control_plane_approval_roles(
                str(approval["action"])
            ),
        )
    except db.MetadataStoreError as exc:
        if workload_issuance:
            raise HTTPException(status_code=409, detail="workload approval could not be recorded") from None
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    finally:
        if workload_receipt is not None:
            from serverware import control_plane_workload_identity_approval as approval_source

            approval_source._discard(workload_receipt)
        if verified_receipt is not None:
            approval_verification._discard(verified_receipt)
    if not updated:
        raise HTTPException(
            status_code=409,
            detail="control-plane approval state changed before it could be approved",
        )
    return updated


@app.post("/api/control-plane/approvals/{approval_id}/deny")
def control_plane_approval_deny(
    approval_id: str,
    payload: ControlPlaneApprovalDecision | None = Body(default=None),
    identity: AdminIdentity = Depends(require_admin),
) -> dict[str, Any]:
    decision = payload if isinstance(payload, ControlPlaneApprovalDecision) else None
    approval = db.get_control_plane_approval(approval_id)
    if not approval:
        raise HTTPException(status_code=404, detail="control-plane approval not found")
    if approval["status"] != "pending":
        raise HTTPException(
            status_code=409,
            detail=f"control-plane approval is already {approval['status']}",
        )
    _assert_control_plane_approval_role(identity, approval["action"])
    updated = db.deny_control_plane_approval(
        approval_id,
        actor_id=identity.user_id,
        note=decision.note if decision else None,
        required_approver_roles=_control_plane_approval_roles(
            str(approval["action"])
        ),
    )
    if not updated:
        raise HTTPException(
            status_code=409,
            detail="control-plane approval state changed before it could be denied",
        )
    if updated["action"] == "credential.oauth.activate" and updated.get("resource_id"):
        updated = {
            **updated,
            "oauthRevocation": _revoke_terminal_pending_oauth_credential(
                updated["resource_id"],
                actor_id=identity.user_id,
            ),
        }
    return updated


