def _record_credential_lease_audit(
    outcome: str,
    payload: CredentialLeaseRequest,
    *,
    authenticated: bool,
    status_code: int,
    reason: str | None = None,
    credential_ids: list[str] | None = None,
    issued_at_epoch_ms: int | None = None,
    expires_at_epoch_ms: int | None = None,
) -> None:
    event = {
        "outcome": outcome,
        "status_code": status_code,
        "reason": reason,
        "recipient_key_id": payload.recipient_key_id,
        "recipient_nonce_sha256": "sha256:"
        + hashlib.sha256(
            payload.recipient_nonce.encode("ascii", errors="replace")
        ).hexdigest(),
        "policy_hash": payload.policy_hash,
        "data_plane_binary_digest": payload.data_plane_binary_digest,
        "purpose": payload.purpose,
        "expected_credential_version": payload.expected_credential_version,
        "expected_metadata_sha256": payload.expected_metadata_sha256,
        "release_attempt_id": (
            payload.release_authorization.attempt_id
            if payload.release_authorization is not None
            else payload.request_authority.attempt_id
            if payload.request_authority is not None
            else None
        ),
        "release_binding_digest": (
            payload.release_authorization.binding_digest
            if payload.release_authorization is not None
            else payload.request_authority.binding_digest
            if payload.request_authority is not None
            else None
        ),
        "release_kind": (
            payload.release_authorization.kind
            if payload.release_authorization is not None
            else None
        ),
        "release_reservation_id": (
            payload.release_authorization.reservation_id
            if payload.release_authorization is not None
            else payload.request_authority.reservation_id
            if payload.request_authority is not None
            else None
        ),
        "release_request_digest": (
            payload.release_authorization.request_digest
            if payload.release_authorization is not None
            else payload.request_authority.request_digest
            if payload.request_authority is not None
            else None
        ),
        "release_operation_digest": (
            payload.release_authorization.operation_digest
            if payload.release_authorization is not None
            else payload.request_authority.operation_digest
            if payload.request_authority is not None
            else None
        ),
        "release_quota_claim_count": (
            len(payload.release_authorization.quota_claims)
            if payload.release_authorization is not None
            else 0
        ),
        "principal_id": payload.principal_id,
        "route_id": payload.route_id,
        "credential_id": payload.credential_id,
        "requested_max_ttl_seconds": payload.max_ttl_seconds,
        "recipient_attestation_present": payload.recipient_attestation is not None,
        "credential_count": len(credential_ids or []),
        "credential_ids": credential_ids or [],
        "issued_at_epoch_ms": issued_at_epoch_ms,
        "expires_at_epoch_ms": expires_at_epoch_ms,
    }
    db.record_audit_event(
        f"data_plane.credential_lease.{outcome}",
        event,
        actor_type="data-plane",
        actor_id=DATA_PLANE_INSTANCE_ID if authenticated else None,
    )


def _should_record_credential_lease_issuance(
    payload: CredentialLeaseRequest,
    credentials: list[dict[str, Any]],
) -> tuple[str, ...] | None:
    state_digest = (
        "sha256:"
        + hashlib.sha256(
            _canonical_json(
                [
                    [item["credentialId"], int(item["credentialVersion"])]
                    for item in credentials
                ]
            ).encode("utf-8")
        ).hexdigest()
    )
    key = (
        payload.purpose,
        payload.recipient_key_id,
        payload.policy_hash,
        payload.data_plane_binary_digest,
        payload.principal_id,
        payload.route_id,
        payload.credential_id,
        (
            payload.release_authorization.attempt_id
            if payload.release_authorization is not None
            else payload.request_authority.attempt_id
            if payload.request_authority is not None
            else ""
        ),
        (
            payload.release_authorization.binding_digest
            if payload.release_authorization is not None
            else payload.request_authority.binding_digest
            if payload.request_authority is not None
            else ""
        ),
        (
            payload.release_authorization.kind
            if payload.release_authorization is not None
            else ""
        ),
        (
            payload.release_authorization.reservation_id
            if payload.release_authorization is not None
            else payload.request_authority.reservation_id
            if payload.request_authority is not None
            else ""
        ),
        state_digest,
    )
    now = time.monotonic()
    with _credential_lease_audit_lock:
        expired = [
            item
            for item, last_recorded in _credential_lease_audit_last.items()
            if last_recorded + _CREDENTIAL_LEASE_AUDIT_INTERVAL_SECONDS <= now
        ]
        for item in expired:
            _credential_lease_audit_last.pop(item, None)
        if key in _credential_lease_audit_last:
            return None
        _credential_lease_audit_last[key] = now
    return key


def _broker_credential_for_lease(credential_id: str) -> dict[str, Any] | None:
    # This preliminary read contains no secret and cannot trigger legacy
    # refresh. The actual ciphertext is read later under the mutation lock.
    credential = db.get_credential(credential_id, include_secret=False)
    if credential is not None and credential.get("kind") == "oauth2":
        raise HTTPException(status_code=503, detail="broker OAuth requires its enrolled current opening")
    return credential


def _credential_for_lease(
    credential_id: str, *, allow_legacy_oauth: bool = True
) -> dict[str, Any] | None:
    from serverware import oauth_application_owner
    if oauth_application_owner.require_started() is not None:
        raise HTTPException(status_code=503, detail="enrolled credentials require the current fenced lease opening")
    credential: dict[str, Any] | None = None
    provider_id: str | None = None
    refreshed: dict[str, Any] | None = None
    try:
        for _ in range(2):
            credential = runtime.get_control_plane_credential(credential_id)
            if not credential or credential.get("kind") != "oauth2":
                return credential
            metadata = credential.get("metadata")
            if not isinstance(metadata, dict) or metadata.get("oauth") is not True:
                return credential
            if not allow_legacy_oauth:
                raise HTTPException(status_code=503, detail="current OAuth credentials require the controlled refresh opening")
            require_application_metadata(metadata)
            expires_at_epoch_ms = metadata.get("expires_at_epoch_ms")
            if not isinstance(expires_at_epoch_ms, int) or isinstance(
                expires_at_epoch_ms, bool
            ):
                raise OAuthError(
                    "managed OAuth credential has no valid access-token expiry"
                )
            now_epoch_ms = time.time_ns() // 1_000_000
            if expires_at_epoch_ms > now_epoch_ms + OAUTH_REFRESH_SKEW_SECONDS * 1000:
                return credential
            provider_id = metadata.get("provider_id")
            if not isinstance(provider_id, str) or not provider_id:
                raise OAuthError("managed OAuth credential has no provider binding")

            with db.oauth_refresh_lock(credential_id):
                runtime.invalidate_secret_leases(credential_id)
                credential = runtime.get_control_plane_credential(credential_id)
                if not credential:
                    return None
                metadata = credential.get("metadata")
                if (
                    credential.get("kind") != "oauth2"
                    or not isinstance(metadata, dict)
                    or metadata.get("oauth") is not True
                ):
                    return credential
                require_application_metadata(metadata)
                provider_id = metadata.get("provider_id")
                if not isinstance(provider_id, str) or not provider_id:
                    raise OAuthError("managed OAuth credential has no provider binding")
                expires_at_epoch_ms = (
                    metadata.get("expires_at_epoch_ms")
                    if isinstance(metadata, dict)
                    else None
                )
                now_epoch_ms = time.time_ns() // 1_000_000
                if (
                    isinstance(expires_at_epoch_ms, int)
                    and not isinstance(expires_at_epoch_ms, bool)
                    and expires_at_epoch_ms
                    > now_epoch_ms + OAUTH_REFRESH_SKEW_SECONDS * 1000
                ):
                    return credential
                token_secret = json.loads(str(credential.get("secret") or ""))
                refreshed = refresh_access_token(
                    provider_id=provider_id,
                    token_secret=token_secret,
                    metadata=metadata,
                    now_epoch=now_epoch_ms // 1000,
                )
                if not isinstance(refreshed, dict):
                    raise OAuthError("OAuth refresh result is malformed")
                refresh_revocation = {
                    "provider": provider_id,
                    "secret": refreshed.get("revocationSecret")
                    or refreshed.get("secret"),
                    "revocationWorkId": refreshed.get("revocationWorkId"),
                }
                refreshed["revocationWorkId"] = _ensure_oauth_exchange_revocation_work(
                    refresh_revocation,
                    actor_id="oauth-refresh",
                )
                refreshed_scopes = _canonical_oauth_granted_scopes(
                    refreshed.get("scopes")
                )
                refreshed_metadata = refreshed.get("metadata")
                if not isinstance(refreshed_metadata, dict):
                    raise OAuthError("OAuth refresh credential metadata is malformed")
                refreshed_metadata_scopes = _canonical_oauth_granted_scopes(
                    refreshed_metadata.get("scopes"),
                    field_name="OAuth refresh credential metadata scopes",
                )
                if refreshed_metadata_scopes != refreshed_scopes:
                    raise OAuthError(
                        "OAuth refresh metadata does not match the provider-granted scopes"
                    )
                refreshed_metadata = {
                    **refreshed_metadata,
                    "scopes": list(refreshed_scopes),
                }
                persisted, rotated = db.update_credential_secret_if_version(
                    credential_id,
                    expected_version=int(credential.get("credential_version") or 0),
                    secret=refreshed["secret"],
                    metadata=refreshed_metadata,
                    revocation_work_id=str(refreshed["revocationWorkId"]),
                    _application_operation=refreshed.get("_application_operation"),
                )
                if not persisted:
                    raise OAuthError("OAuth credential disappeared during refresh")
                if not rotated:
                    if int(persisted.get("credential_version") or 0) != int(
                        credential.get("credential_version") or 0
                    ):
                        _revoke_rejected_oauth_refresh(
                            refreshed,
                            provider_id=provider_id,
                            rejection_reason="OAuth credential changed during refresh",
                        )
                        refreshed = None
                        runtime.invalidate_secret_leases(credential_id)
                        continue
                    refreshed = None
                    runtime.invalidate_secret_leases(credential_id)
                    return persisted
                persisted_refresh = refreshed
                refreshed = None
                runtime.invalidate_secret_leases(credential_id)
                db.record_audit_event(
                    "credential.oauth_refreshed",
                    {
                        "credential_id": credential_id,
                        "provider": provider_id,
                        "previous_credential_version": credential.get(
                            "credential_version"
                        ),
                        "credential_version": persisted.get("credential_version"),
                        "expires_at_epoch_ms": persisted_refresh["expiresAtEpochMs"],
                        "refresh_token_rotated": persisted_refresh[
                            "refreshTokenRotated"
                        ],
                        "scopes": list(refreshed_scopes),
                    },
                    actor_type="system",
                    actor_id="oauth-refresh",
                )
                return persisted
        raise OAuthError("OAuth credential changed repeatedly during refresh")
    except (OAuthError, ValueError, TypeError, json.JSONDecodeError) as exc:
        if isinstance(refreshed, dict) and isinstance(provider_id, str):
            _revoke_rejected_oauth_refresh(
                refreshed,
                provider_id=provider_id,
                rejection_reason=str(exc),
            )
            refreshed = None
        try:
            db.record_audit_event(
                "credential.oauth_refresh_failed",
                {
                    "credential_id": credential_id,
                    "provider": provider_id,
                    "credential_version": credential.get("credential_version"),
                    "reason": type(exc).__name__,
                },
                actor_type="system",
                actor_id="oauth-refresh",
            )
        except Exception:
            pass
        raise HTTPException(
            status_code=503,
            detail="OAuth access token could not be refreshed; reconnect the provider account",
        ) from exc


def _normalized_credential_provider(value: Any) -> str:
    provider = str(value or "").strip().lower()
    aliases = {
        "twitter": "x",
        "x.oauth": "x",
        "x.oauth2": "x",
        "google.oauth": "google",
        "google.oauth2": "google",
    }
    return aliases.get(provider, provider)


def _credential_metadata_scopes(metadata: dict[str, Any]) -> frozenset[str]:
    populated = [
        metadata[name]
        for name in ("scopes", "scope")
        if metadata.get(name) is not None
    ]
    if not populated:
        return frozenset()
    normalized: list[frozenset[str]] = []
    for raw_scopes in populated:
        if isinstance(raw_scopes, str):
            scopes = [item for item in raw_scopes.split() if item]
        elif isinstance(raw_scopes, list) and all(
            isinstance(item, str)
            and item
            and item == item.strip()
            and not any(character.isspace() for character in item)
            for item in raw_scopes
        ):
            scopes = raw_scopes
        else:
            raise HTTPException(
                status_code=503, detail="credential scope metadata is invalid"
            )
        if len(scopes) != len(set(scopes)):
            raise HTTPException(
                status_code=503,
                detail="credential scope metadata contains duplicates",
            )
        normalized.append(frozenset(scopes))
    if any(scopes != normalized[0] for scopes in normalized[1:]):
        raise HTTPException(
            status_code=409,
            detail="credential scope metadata aliases are contradictory",
        )
    return normalized[0]


def _credential_metadata_binding_alias(
    metadata: dict[str, Any],
    names: tuple[str, ...],
    *,
    label: str,
    normalize: Callable[[Any], str] | None = None,
) -> str:
    values: list[str] = []
    normalized: list[str] = []
    for name in names:
        if metadata.get(name) is None:
            continue
        value = metadata[name]
        if (
            not isinstance(value, str)
            or not value
            or value != value.strip()
            or len(value.encode("utf-8")) > 2048
            or any(ord(character) < 32 or ord(character) == 127 for character in value)
        ):
            raise HTTPException(
                status_code=409,
                detail=f"stored credential {label} metadata is invalid",
            )
        values.append(value)
        normalized.append(normalize(value) if normalize is not None else value)
    if not values or any(value != normalized[0] for value in normalized[1:]):
        raise HTTPException(
            status_code=409,
            detail=f"stored credential {label} metadata is missing or contradictory",
        )
    return normalized[0]


def _assert_credential_policy_binding(
    credential: dict[str, Any], credential_policy: Any
) -> None:
    metadata = credential.get("metadata") or {}
    if not isinstance(metadata, dict):
        raise HTTPException(status_code=503, detail="credential metadata is invalid")
    policy_provider = _normalized_credential_provider(credential_policy.provider)
    stored_provider = _credential_metadata_binding_alias(
        metadata,
        ("provider_id", "provider"),
        label="provider",
        normalize=_normalized_credential_provider,
    )
    if stored_provider != policy_provider:
        raise HTTPException(
            status_code=409,
            detail="stored credential provider does not match the active signed policy",
        )
    if credential.get("kind") == "oauth2":
        if credential_policy.kind != "oauth2":
            raise HTTPException(
                status_code=409,
                detail="stored OAuth credential type does not match the active signed policy",
            )
        try:
            verified_provider, stored_subject = db.validate_managed_oauth_identity(
                metadata
            )
        except db.ManagedOAuthCredentialError as exc:
            raise HTTPException(status_code=409, detail=str(exc)) from exc
        if _normalized_credential_provider(verified_provider) != policy_provider:
            raise HTTPException(
                status_code=409,
                detail="verified OAuth provider does not match the active signed policy",
            )
        stored_subject_alias = _credential_metadata_binding_alias(
            metadata,
            ("provider_subject", "account_subject"),
            label="provider subject",
        )
        if not hmac.compare_digest(stored_subject_alias, stored_subject):
            raise HTTPException(
                status_code=409,
                detail="stored OAuth subject aliases do not match the verified identity",
            )
        policy_subject = credential_policy.provider_subject
        if (
            not isinstance(policy_subject, str)
            or not policy_subject
            or stored_subject != policy_subject
        ):
            raise HTTPException(
                status_code=409,
                detail="stored OAuth account does not match the active signed policy",
            )
        stored_client_id = _credential_metadata_binding_alias(
            metadata,
            ("oauth_client_id", "client_id", "x_app_id", "app_id"),
            label="OAuth client ID",
        )
        if (
            not isinstance(credential_policy.oauth_client_id, str)
            or not hmac.compare_digest(
                stored_client_id, credential_policy.oauth_client_id
            )
        ):
            raise HTTPException(
                status_code=409,
                detail="stored OAuth client does not match the active signed policy",
            )
        try:
            stored_scopes = frozenset(
                _canonical_oauth_granted_scopes(
                    list(_credential_metadata_scopes(metadata)),
                    field_name="OAuth credential metadata scopes",
                )
            )
            policy_scopes = frozenset(
                _canonical_oauth_granted_scopes(
                    list(credential_policy.scopes),
                    field_name="signed policy OAuth scopes",
                )
            )
        except OAuthError as exc:
            raise HTTPException(status_code=503, detail=str(exc)) from exc
    else:
        if credential_policy.kind != "static":
            raise HTTPException(
                status_code=409,
                detail="stored static credential type does not match the active signed policy",
            )
        stored_subject = _credential_metadata_binding_alias(
            metadata,
            ("provider_subject", "account_subject"),
            label="provider subject",
        )
        if (
            not isinstance(credential_policy.provider_subject, str)
            or not hmac.compare_digest(
                stored_subject, credential_policy.provider_subject
            )
        ):
            raise HTTPException(
                status_code=409,
                detail="stored credential account does not match the active signed policy",
            )
        policy_scopes = frozenset(str(item) for item in credential_policy.scopes)
        stored_scopes = _credential_metadata_scopes(metadata)
    if stored_scopes != policy_scopes:
        raise HTTPException(
            status_code=409,
            detail="stored credential scopes do not exactly match the active signed policy",
        )


def _assert_credential_injection_binding(
    credential: dict[str, Any], credential_policy: Any
) -> None:
    metadata = credential.get("metadata") or {}
    if not isinstance(metadata, dict):
        raise HTTPException(status_code=503, detail="credential metadata is invalid")
    stored_kind = str(credential.get("kind") or "")
    injection = (
        credential_policy.injection
        if isinstance(credential_policy.injection, dict)
        else {}
    )
    injection_type = str(injection.get("type") or "")
    expected_type = "bearer" if stored_kind == "oauth2" else stored_kind
    if not expected_type or injection_type != expected_type:
        raise HTTPException(
            status_code=409,
            detail="stored credential kind does not match the signed policy injection type",
        )
    if stored_kind == "oauth2" and (
        str(injection.get("header") or "Authorization").lower() != "authorization"
        or injection.get("field") != "access_token"
        or injection.get("prefix", "Bearer ") != "Bearer "
    ):
        raise HTTPException(
            status_code=409,
            detail="managed OAuth credentials require canonical access-token-only bearer injection",
        )
    if injection_type in {"header", "query", "cookie"} and injection.get(
        "name"
    ) != metadata.get("injection_name"):
        raise HTTPException(
            status_code=409,
            detail="stored credential injection name does not match the signed policy",
        )
    if injection_type == "basic" and injection.get("username") != metadata.get(
        "username"
    ):
        raise HTTPException(
            status_code=409,
            detail="stored credential Basic username does not match the signed policy",
        )
    if metadata.get("injection_field") is not None and injection.get(
        "field"
    ) != metadata.get("injection_field"):
        raise HTTPException(
            status_code=409,
            detail="stored credential injection field does not match the signed policy",
        )
    if metadata.get("injection_prefix") is not None and injection.get(
        "prefix"
    ) != metadata.get("injection_prefix"):
        raise HTTPException(
            status_code=409,
            detail="stored credential injection prefix does not match the signed policy",
        )


def _assert_route_credential_binding(
    route: Any,
    credential: dict[str, Any],
    credential_policy: Any,
) -> None:
    metadata = credential.get("metadata") or {}
    if not isinstance(metadata, dict):
        raise HTTPException(status_code=503, detail="credential metadata is invalid")
    binding = route.adapter_config.get("credentialBinding")
    if not isinstance(binding, dict):
        raise HTTPException(
            status_code=409,
            detail=f"route {route.id} has no exact credential binding",
        )
    policy_provider = _normalized_credential_provider(credential_policy.provider)
    if (
        binding.get("credentialType") != credential_policy.kind
        or _normalized_credential_provider(binding.get("provider"))
        != policy_provider
        or binding.get("subjects") != [credential_policy.provider_subject]
    ):
        raise HTTPException(
            status_code=409,
            detail=f"route {route.id} does not exactly bind the signed credential identity",
        )

    if credential.get("kind") == "oauth2":
        client_id = _credential_metadata_binding_alias(
            metadata,
            ("oauth_client_id", "client_id", "x_app_id", "app_id"),
            label="OAuth client ID",
        )
        required_scopes = binding.get("requiredScopes")
        stored_scopes = _credential_metadata_scopes(metadata)
        if (
            binding.get("clientIds") != [client_id]
            or not isinstance(required_scopes, list)
            or not required_scopes
            or len(required_scopes) != len(set(required_scopes))
            or not all(isinstance(scope, str) and scope for scope in required_scopes)
            or not set(required_scopes).issubset(stored_scopes)
        ):
            raise HTTPException(
                status_code=409,
                detail=f"route {route.id} does not exactly bind the stored OAuth grant",
            )
        if route.adapter_type == "x.v2" and route.adapter_config.get("appIds") != [
            client_id
        ]:
            raise HTTPException(
                status_code=409,
                detail=f"route {route.id} does not exactly bind the stored X app",
            )
        return

    secret_class = _credential_metadata_binding_alias(
        metadata,
        ("secret_class", "token_class"),
        label="secret class",
    )
    if binding.get("secretClass") != secret_class:
        raise HTTPException(
            status_code=409,
            detail=f"route {route.id} does not bind the stored secret class",
        )


def _assert_policy_candidate_credential_bindings(snapshot: Any) -> None:
    stored_credentials: dict[str, dict[str, Any]] = {}
    for credential_id, credential_policy in snapshot.credentials.items():
        credential = db.get_credential(credential_id)
        if credential is None:
            raise HTTPException(
                status_code=409,
                detail=f"credential {credential_id} is missing or inactive",
            )
        try:
            _assert_credential_policy_binding(credential, credential_policy)
            _assert_credential_injection_binding(credential, credential_policy)
        except HTTPException as exc:
            raise HTTPException(
                status_code=exc.status_code,
                detail=f"credential {credential_id}: {exc.detail}",
            ) from exc
        stored_credentials[credential_id] = credential

    for route in snapshot.routes:
        credential_id = route.credential_ref
        if not credential_id:
            continue
        credential = stored_credentials.get(credential_id)
        if credential is None:
            raise HTTPException(
                status_code=409,
                detail=f"credential {credential_id} is missing or inactive",
            )
        try:
            _assert_route_credential_binding(
                route, credential, snapshot.credentials[credential_id]
            )
        except HTTPException as exc:
            raise HTTPException(
                status_code=exc.status_code,
                detail=f"credential {credential_id}: {exc.detail}",
            ) from exc


def _credential_secret_for_lease(
    credential: dict[str, Any], credential_policy: Any
) -> str:
    secret = str(credential.get("secret") or "")
    if credential.get("kind") != "oauth2":
        return secret
    injection = (
        credential_policy.injection
        if isinstance(credential_policy.injection, dict)
        else {}
    )
    if (
        injection.get("type") != "bearer"
        or str(injection.get("header") or "Authorization").lower() != "authorization"
        or injection.get("field") != "access_token"
        or injection.get("prefix", "Bearer ") != "Bearer "
    ):
        raise HTTPException(
            status_code=409,
            detail="managed OAuth credentials require canonical access-token-only bearer injection",
        )

    def reject_duplicate_keys(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("duplicate OAuth token field")
            result[key] = value
        return result

    try:
        token = json.loads(secret, object_pairs_hook=reject_duplicate_keys)
    except (TypeError, ValueError, json.JSONDecodeError) as exc:
        raise HTTPException(
            status_code=503,
            detail="managed OAuth credential token material is malformed",
        ) from exc
    access_token = token.get("access_token") if isinstance(token, dict) else None
    if (
        not isinstance(access_token, str)
        or not access_token
        or len(access_token.encode("utf-8")) > 64 * 1024
    ):
        raise HTTPException(
            status_code=503, detail="managed OAuth access token is missing or oversized"
        )
    return _canonical_json({"access_token": access_token})


def _assert_credential_lease_route_binding(
    payload: CredentialLeaseRequest, snapshot: Any
) -> Any:
    if not hmac.compare_digest(snapshot.hash, payload.policy_hash):
        raise HTTPException(
            status_code=409, detail="data-plane policy hash is not active"
        )
    route = _active_route_by_id(payload.route_id, snapshot=snapshot)
    if payload.principal_id not in route.principals and "*" not in route.principals:
        raise HTTPException(
            status_code=409,
            detail="principal is not assigned to the requested active route",
        )
    profile, _ = lease_profiles.request_representation(payload.api_version)
    if route.credential_ref is None or not lease_profiles.text_matches(
        route.credential_ref, payload.credential_id, native=profile in {"native", "native-broker"}, policy_aware=profile == "policy-aware"
    ):
        raise HTTPException(
            status_code=409,
            detail="credential does not match the requested active route",
        )
    credential_policy = snapshot.credentials.get(payload.credential_id)
    if credential_policy is None:
        raise HTTPException(
            status_code=409, detail="credential is not declared by the active policy"
        )
    return credential_policy


_CREDENTIAL_LEASE_PUBLIC_METADATA_FIELDS = frozenset(
    {
        "account_subject",
        "app_id",
        "client_id",
        "expires_at_epoch_ms",
        "injection_field",
        "injection_name",
        "injection_prefix",
        "managed",
        "oauth",
        "oauth_client_id",
        "provider",
        "provider_id",
        "provider_identity_verified",
        "provider_subject",
        "scope",
        "scopes",
        "secret_class",
        "subject",
        "token_class",
        "username",
        "x_app_id",
    }
)
_CREDENTIAL_LEASE_PUBLIC_METADATA_BOOLEAN_FIELDS = frozenset(
    {"managed", "oauth", "provider_identity_verified"}
)
_CREDENTIAL_LEASE_PUBLIC_METADATA_STRING_FIELDS = (
    _CREDENTIAL_LEASE_PUBLIC_METADATA_FIELDS
    - _CREDENTIAL_LEASE_PUBLIC_METADATA_BOOLEAN_FIELDS
    - {"expires_at_epoch_ms", "scopes"}
)


def _credential_lease_request_binding_sha256(
    payload: CredentialLeaseRequest,
) -> str:
    request_authority = (
        payload.request_authority.model_dump(
            by_alias=True,
            exclude_unset=True,
        )
        if payload.request_authority is not None
        else None
    )
    release_authorization = (
        payload.release_authorization.model_dump(
            by_alias=True,
            exclude_unset=True,
        )
        if payload.release_authorization is not None
        else None
    )
    return "sha256:" + hashlib.sha256(
        _canonical_json(
            {
                "apiVersion": payload.api_version,
                "purpose": payload.purpose,
                "principalId": payload.principal_id,
                "routeId": payload.route_id,
                "credentialId": payload.credential_id,
                "expectedCredentialVersion": payload.expected_credential_version,
                "expectedMetadataSha256": payload.expected_metadata_sha256,
                "requestAuthority": request_authority,
                "releaseAuthorization": release_authorization,
                "recipientKeyId": payload.recipient_key_id,
                "recipientNonce": payload.recipient_nonce,
                "policyHash": payload.policy_hash,
                "dataPlaneBinaryDigest": payload.data_plane_binary_digest,
                "maxTtlSeconds": payload.max_ttl_seconds,
            }
        ).encode("utf-8")
    ).hexdigest()


def _credential_lease_request_authority_sha256(
    authority: CredentialLeaseRequestAuthority,
) -> str:
    return "sha256:" + hashlib.sha256(
        _canonical_json(
            authority.model_dump(by_alias=True, exclude_unset=True)
        ).encode("utf-8")
    ).hexdigest()


def _credential_lease_secret_patterns(secret: str) -> tuple[str, ...]:
    values = {secret}
    try:
        parsed = json.loads(secret)
    except (TypeError, ValueError, json.JSONDecodeError):
        parsed = None

    def collect(value: Any) -> None:
        if isinstance(value, str) and value:
            values.add(value)
        elif isinstance(value, dict):
            for item in value.values():
                collect(item)
        elif isinstance(value, list):
            for item in value:
                collect(item)

    collect(parsed)
    patterns: set[str] = set()
    for value in values:
        if not value:
            continue
        raw = value.encode("utf-8")
        digest = hashlib.sha256(raw).hexdigest()
        patterns.update(
            {
                value,
                json.dumps(value, ensure_ascii=True)[1:-1],
                base64.b64encode(raw).decode("ascii"),
                base64.urlsafe_b64encode(raw).decode("ascii").rstrip("="),
                digest,
                f"sha256:{digest}",
            }
        )
    return tuple(sorted((item for item in patterns if item), key=len, reverse=True))


def _credential_lease_public_metadata(credential: dict[str, Any]) -> dict[str, Any]:
    raw_metadata = credential.get("metadata") or {}
    if not isinstance(raw_metadata, dict):
        raise HTTPException(status_code=503, detail="credential metadata is invalid")
    metadata = {
        key: raw_metadata[key]
        for key in sorted(_CREDENTIAL_LEASE_PUBLIC_METADATA_FIELDS)
        if key in raw_metadata
    }
    for key, value in metadata.items():
        if key in _CREDENTIAL_LEASE_PUBLIC_METADATA_BOOLEAN_FIELDS:
            if not isinstance(value, bool):
                raise HTTPException(
                    status_code=503,
                    detail=f"credential public metadata field {key} must be boolean",
                )
        elif key in _CREDENTIAL_LEASE_PUBLIC_METADATA_STRING_FIELDS:
            if not isinstance(value, str) or not value or len(value.encode("utf-8")) > 4096:
                raise HTTPException(
                    status_code=503,
                    detail=f"credential public metadata field {key} must be a bounded non-empty string",
                )
        elif key == "expires_at_epoch_ms":
            if (
                not isinstance(value, int)
                or isinstance(value, bool)
                or value < 1
            ):
                raise HTTPException(
                    status_code=503,
                    detail="credential public metadata field expires_at_epoch_ms must be positive",
                )
        elif key == "scopes":
            if (
                not isinstance(value, list)
                or len(value) > 128
                or any(
                    not isinstance(item, str)
                    or not item
                    or len(item.encode("utf-8")) > 4096
                    for item in value
                )
                or len(set(value)) != len(value)
            ):
                raise HTTPException(
                    status_code=503,
                    detail="credential public metadata field scopes must be a bounded unique string array",
                )
    try:
        encoded = _canonical_json(metadata)
    except (TypeError, ValueError) as exc:
        raise HTTPException(
            status_code=503, detail="credential public metadata is invalid"
        ) from exc
    if len(encoded.encode("utf-8")) > 64 * 1024:
        raise HTTPException(
            status_code=503, detail="credential public metadata exceeds 64 KiB"
        )
    secret = str(credential.get("secret") or "")
    if secret and any(pattern in encoded for pattern in _credential_lease_secret_patterns(secret)):
        raise HTTPException(
            status_code=503,
            detail="credential public metadata contains secret-derived material",
        )
    if _data_plane_audit_secret_path(metadata) is not None:
        raise HTTPException(
            status_code=503, detail="credential public metadata contains secret material"
        )
    return metadata


def _credential_lease_metadata_sha256(metadata: dict[str, Any]) -> str:
    return "sha256:" + hashlib.sha256(
        _canonical_json(metadata).encode("utf-8")
    ).hexdigest()


def _assert_credential_lease_release_authorization(
    payload: CredentialLeaseRequest,
    *,
    route: Any,
) -> dict[str, Any]:
    profile, bound = lease_profiles.request_representation(payload.api_version)
    native, policy_aware = profile in {"native", "native-broker"}, profile == "policy-aware"
    release = payload.release_authorization
    jit = route.jit if isinstance(route.jit, dict) else {}
    jit_required = jit.get("required") is True
    if payload.purpose == "generationMetadata":
        return {
            "controlled": False,
            "issuanceKind": None,
            "requestAuthority": None,
            "requestAuthoritySha256": None,
            "releaseAuthorization": None,
        }
    shared_route_present = any(
        isinstance(constraint, dict)
        and constraint.get("type") == "rateLimit"
        and constraint.get("store", "local") == "shared"
        and constraint.get("phase", "request") == "request"
        for constraint in route.constraints
    )
    durable_policy_route_present = any(
        isinstance(constraint, dict)
        and constraint.get("type")
        in {
            "slidingWindowLimit",
            "weightedBudget",
            "traversalBudget",
        }
        for constraint in route.constraints
    )
    route_controlled = (
        jit_required or shared_route_present or durable_policy_route_present
    )
    if not route_controlled:
        if (
            bound
            or payload.request_authority is not None
            or release is not None
        ):
            raise HTTPException(
                status_code=409,
                detail="uncontrolled route requires authority-free credential dispatch",
            )
        return {
            "controlled": False,
            "issuanceKind": None,
            "requestAuthority": None,
            "requestAuthoritySha256": None,
            "releaseAuthorization": None,
        }
    if (
        not bound
        or payload.request_authority is None
    ):
        raise HTTPException(
            status_code=409,
            detail="controlled route requires an operation-bound credential lease profile",
        )
    if not ATOMIC_RELEASE_AUTHORIZATION_ENABLED:
        raise HTTPException(
            status_code=503,
            detail="controlled credential dispatch requires atomic request authority",
        )
    authority = payload.request_authority
    authority_wire = authority.model_dump(
        by_alias=True,
        exclude_unset=True,
    )
    authority_sha256 = _credential_lease_request_authority_sha256(authority)
    now_epoch_ms = time.time_ns() // 1_000_000
    # Prepared request authority must recheck the same complete current JIT
    # normalization used by preparation, reservation, and the issuance claim.
    jit_authority = db.jit_approver_policy_arguments(jit) if (native or policy_aware) and jit_required else {}
    try:
        authority_snapshot = db.release_credential_request_authority_snapshot(
            attempt_id=authority.attempt_id,
            reservation_id=authority.reservation_id,
            binding_digest=authority.binding_digest,
            request_digest=authority.request_digest,
            operation_digest=authority.operation_digest,
            operation_context=authority.operation_context,
            reservation_expires_at_epoch_ms=(
                authority.reservation_expires_at_epoch_ms
            ),
            principal_id=payload.principal_id,
            route_id=payload.route_id,
            credential_id=payload.credential_id,
            credential_version=int(payload.expected_credential_version or 0),
            policy_hash=payload.policy_hash,
            native_profile=native,
            policy_aware_profile=policy_aware,
            now_epoch_ms=now_epoch_ms,
            required_approver_roles=({"approver"} if jit_required else set()),
            allowed_approver_ids=(
                set((jit.get("approvers") or {}).get("users") or []) or None
                if jit_required
                else None
            ),
            require_approver_webauthn=(
                bool(jit_authority.get("require_approver_webauthn"))
                if native or policy_aware
                else _webauthn_required(_approval_authn_policy(jit))
                if jit_required
                else False
            ),
            approval_threshold=int(jit_authority.get("approval_threshold", 1)),
            approver_credential_policy=jit_authority.get("approver_credential_policy"),
        )
    except db.ReleaseAuthorizationConflictError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    except db.ReleaseAuthorizationError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    except Exception as exc:
        raise HTTPException(
            status_code=503,
            detail="credential lease request authority is unavailable",
        ) from exc
    if not hmac.compare_digest(
        authority_snapshot["request_authority_sha256"],
        authority_sha256,
    ):
        raise HTTPException(
            status_code=409,
            detail="credential lease request authority digest mismatch",
        )
    if (authority_snapshot["native_profile"] is not native
            or authority_snapshot["policy_aware_profile"] is not policy_aware):
        raise HTTPException(status_code=409, detail="credential lease retained release profile mismatch")

    committed_operation = authority_snapshot["operation_context"].get(
        "operation"
    )
    durable_required = False
    for constraint in route.constraints:
        if not isinstance(constraint, dict):
            raise HTTPException(
                status_code=503,
                detail="active route constraint is invalid",
            )
        constraint_type = constraint.get("type")
        if constraint_type in {"slidingWindowLimit", "weightedBudget"}:
            durable_required = True
        elif constraint_type == "traversalBudget":
            operations = constraint.get("operations")
            if operations is None:
                durable_required = True
            elif (
                not isinstance(operations, list)
                or any(
                    not isinstance(item, str) or not item
                    for item in operations
                )
            ):
                raise HTTPException(
                    status_code=503,
                    detail="active traversal operation scope is invalid",
                )
            elif committed_operation in operations:
                durable_required = True
    quota_claims = authority_snapshot["quota_claims"]
    expected_shared_quotas = _expected_release_authorization_shared_quotas(
        route=route,
        principal_id=payload.principal_id,
        credential_version=int(payload.expected_credential_version or 0),
        operation_context=authority_snapshot["operation_context"],
    )
    actual_shared_quotas = sorted(
        (
            {
                "counter_key": claim["counterKey"],
                "constraint_id": claim["constraintId"],
                "operation": claim["operation"],
                "window_kind": claim["windowKind"],
                "window_seconds": claim["windowSeconds"],
                "max_count": claim["max"],
            }
            for claim in quota_claims
        ),
        key=lambda item: item["counter_key"],
    )
    if not hmac.compare_digest(
        _canonical_json(actual_shared_quotas),
        _canonical_json(expected_shared_quotas),
    ):
        raise HTTPException(
            status_code=409,
            detail="request authority shared quota claims conflict with active policy",
        )
    durable_snapshot = authority_snapshot["durable_policy"]
    if durable_required:
        if (
            authority_snapshot["release_protocol"] != "v2"
            or not isinstance(durable_snapshot, dict)
            or durable_snapshot.get("state") != "reserved"
            or durable_snapshot.get("actorId") != DATA_PLANE_INSTANCE_ID
        ):
            raise HTTPException(
                status_code=409,
                detail="committed operation lacks exact durable release authority",
            )
        expected_durable = {
            key: durable_snapshot[key]
            for key in (
                "reservationId",
                "actorId",
                "claimDigest",
                "reservationDeadlineAtEpochMs",
                "releaseBindingDigest",
            )
        }
    else:
        if (
            authority_snapshot["release_protocol"] != "v1"
            or durable_snapshot is not None
        ):
            raise HTTPException(
                status_code=409,
                detail="request authority carries inapplicable durable release state",
            )
        expected_durable = None

    grant_id = authority_snapshot["grant_id"]
    approval_request_id = authority_snapshot["approval_request_id"]
    grant_pair_present = (
        isinstance(grant_id, str)
        and bool(grant_id)
        and isinstance(approval_request_id, str)
        and bool(approval_request_id)
    )
    if (
        (grant_id is None) != (approval_request_id is None)
        or jit_required != grant_pair_present
    ):
        raise HTTPException(
            status_code=409,
            detail="request authority JIT grant state conflicts with active policy",
        )
    expected_kind = (
        "jitGrant"
        if jit_required
        else "atomicReservation"
        if quota_claims or durable_required
        else "decisionBound"
    )
    if expected_kind == "decisionBound":
        if release is not None:
            raise HTTPException(
                status_code=409,
                detail="decision-bound operation must omit durable release authorization",
            )
        release_wire = None
    else:
        if release is None:
            raise HTTPException(
                status_code=409,
                detail="controlled operation requires exact release authorization",
            )
        expected_release = {
            "apiVersion": lease_profiles.release_version(native=native, durable=durable_required, policy_aware=policy_aware),
            "kind": expected_kind,
            "state": "reserved",
            "attemptId": authority.attempt_id,
            "reservationId": authority.reservation_id,
            "bindingDigest": authority.binding_digest,
            "principalId": payload.principal_id,
            "routeId": payload.route_id,
            "credentialId": payload.credential_id,
            "credentialVersion": payload.expected_credential_version,
            "policyHash": payload.policy_hash,
            "requestDigest": authority.request_digest,
            "operationDigest": authority.operation_digest,
            "quotaClaims": quota_claims,
            "grantId": grant_id,
            "approvalRequestId": approval_request_id,
            "reservationExpiresAtEpochMs": (
                authority.reservation_expires_at_epoch_ms
            ),
        }
        if expected_durable is not None:
            expected_release["durablePolicy"] = expected_durable
        release_wire = release.model_dump(
            by_alias=True,
            exclude_unset=True,
        )
        if not hmac.compare_digest(
            _canonical_json(release_wire),
            _canonical_json(expected_release),
        ):
            raise HTTPException(
                status_code=409,
                detail="credential release authorization does not match request authority",
            )
    return {
        "controlled": True,
        "issuanceKind": expected_kind,
        "requestAuthority": authority_wire,
        "requestAuthoritySha256": authority_sha256,
        "releaseAuthorization": release_wire,
        "authoritySnapshot": authority_snapshot,
    }


def _claim_credential_lease_release_authorization(
    payload: CredentialLeaseRequest,
    *,
    route: Any,
    dispatch_authority: dict[str, Any],
    request_binding_sha256: str,
    recipient_nonce_sha256: str,
) -> dict[str, Any] | None:
    release = payload.release_authorization
    request_authority = payload.request_authority
    if (
        payload.purpose != "dispatchSecret"
        or not dispatch_authority["controlled"]
    ):
        return None
    if request_authority is None:
        raise HTTPException(
            status_code=409,
            detail="controlled credential issuance is missing request authority",
        )
    jit = route.jit if isinstance(route.jit, dict) else {}
    jit_authority = (
        db.jit_approver_policy_arguments(jit)
        if dispatch_authority["issuanceKind"] == "jitGrant"
        else {}
    )
    profile, _ = lease_profiles.request_representation(payload.api_version)
    try:
        return db.claim_release_credential_issuance(
            native_profile=profile in {"native", "native-broker"},
            policy_aware_profile=profile == "policy-aware",
            release_kind=str(dispatch_authority["issuanceKind"]),
            attempt_id=request_authority.attempt_id,
            reservation_id=request_authority.reservation_id,
            binding_digest=request_authority.binding_digest,
            request_digest=request_authority.request_digest,
            operation_digest=request_authority.operation_digest,
            operation_context=request_authority.operation_context,
            quota_claims=[
                claim.model_dump(by_alias=True)
                for claim in (release.quota_claims if release is not None else [])
            ],
            durable_policy=(
                release.durable_policy.model_dump(by_alias=True)
                if release is not None and release.durable_policy is not None
                else None
            ),
            actor_id=DATA_PLANE_INSTANCE_ID,
            request_binding_sha256=request_binding_sha256,
            request_authority_sha256=str(
                dispatch_authority["requestAuthoritySha256"]
            ),
            recipient_key_id=payload.recipient_key_id,
            recipient_nonce_sha256=recipient_nonce_sha256,
            principal_id=payload.principal_id,
            route_id=payload.route_id,
            credential_id=payload.credential_id,
            credential_version=int(payload.expected_credential_version or 0),
            policy_hash=payload.policy_hash,
            grant_id=release.grant_id if release is not None else None,
            approval_request_id=(
                release.approval_request_id if release is not None else None
            ),
            reservation_expires_at_epoch_ms=(
                request_authority.reservation_expires_at_epoch_ms
            ),
            required_approver_roles=(
                jit_authority.get("required_approver_roles", set())
            ),
            allowed_approver_ids=jit_authority.get(
                "allowed_approver_ids"
            ),
            require_approver_webauthn=bool(
                jit_authority.get(
                    "require_approver_webauthn",
                    False,
                )
            ),
            approval_threshold=int(
                jit_authority.get("approval_threshold", 1)
            ),
            approver_credential_policy=jit_authority.get(
                "approver_credential_policy"
            ),
        )
    except db.ReleaseAuthorizationConflictError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    except db.ReleaseAuthorizationError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc


@app.post("/api/data-plane/credential-currentness")
def data_plane_credential_currentness(
    request: Request,
    payload: CredentialCurrentnessRequest = Depends(_bounded_credential_currentness_request),
) -> Response:
    from serverware import control_plane_credential_currentness as currentness

    try:
        if not currentness.selected():
            raise HTTPException(status_code=503, detail="measured credential currentness is not configured")
        _require_currentness_response_context(request, "/api/data-plane/credential-currentness")
        original = _original_data_plane_request(request, _CREDENTIAL_CURRENTNESS_ORIGINAL_SCOPE_KEY, payload)
        result = currentness.on_request(request, original)
        body = _canonical_json(result).encode("utf-8")
        if len(body) > _SIGNED_RESPONSE_MAX_BYTES:
            raise HTTPException(status_code=503, detail="credential currentness response exceeds its bound")
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=503, detail="credential currentness is unavailable") from exc
    # The existing ASGI response signer binds the actual nonce, request and
    # final body. An observation never substitutes for a dispatch capability.
    return Response(content=body, media_type="application/json", headers={"Cache-Control": "no-store"})


@app.post("/api/data-plane/oauth-refresh")
async def data_plane_measured_oauth_refresh(request: Request) -> Response:
    from serverware import control_plane_oauth_measured_refresh as measured
    _require_data_plane_token(request.headers.get("X-Serverware-Data-Plane-Token"), DATA_PLANE_CREDENTIAL_LEASE_TOKEN)
    if request.query_params or request.headers.get("content-type", "").split(";", 1)[0].strip().lower() != "application/json":
        raise HTTPException(status_code=400, detail="measured refresh requires its fixed JSON original")
    original = bytearray()
    async for chunk in request.stream():
        original.extend(chunk)
        if len(original) > measured.MAX_REQUEST:
            raise HTTPException(status_code=413, detail="measured refresh request exceeds its bound")
    try:
        # Opening/dispatch stay on one actual worker thread. This route never
        # decrypts credentials or acquires an ambient runtime SQL writer.
        from starlette.concurrency import run_in_threadpool
        result = await run_in_threadpool(measured.on_request, request, bytes(original))
        body = _canonical_json(result).encode("utf-8")
    except Exception as exc:
        raise HTTPException(status_code=503, detail="measured refresh is unavailable; no retry is authorized") from exc
    return Response(content=body, media_type="application/json", headers={"Cache-Control": "no-store"})


